#ifndef CC_RAYTRACER_SHADERS_H
#define CC_RAYTRACER_SHADERS_H

static const char* const RT_TRACE_SRC =
	"#version 430\n"
	"/* Shared code for the ClassiCube GPU voxel path tracer (see src/RayTracer.c)\n"
	"   The world is traced directly as a voxel grid using a 3D DDA walk, so no\n"
	"   acceleration structure has to be built or maintained on block changes.\n"
	"   Copyright 2014-2025 ClassiCube | Licensed under BSD-3 */\n"
	"\n"
	"/* Must match struct RTParams in RayTracer.c (std140 layout, vec4/mat4 only) */\n"
	"layout(std140, binding = 0) uniform Params {\n"
	"	mat4  invViewProj;  /* clip space -> world space */\n"
	"	mat4  viewProj;     /* world space -> clip space (current frame) */\n"
	"	mat4  prevViewProj; /* world space -> clip space (previous frame) */\n"
	"	mat4  view;         /* world space -> eye space */\n"
	"	vec4  camPos;       /* xyz = camera position, w = time in seconds */\n"
	"	vec4  sunDir;       /* xyz = direction towards the sun, w = tan(sun angular radius) */\n"
	"	vec4  sunCol, sunXSide, sunZSide, sunYMin;\n"
	"	vec4  shadowCol, shadowXSide, shadowZSide, shadowYMin;\n"
	"	vec4  skyCol;       /* rgb = colour seen by rays that escape the world */\n"
	"	vec4  fogCol;       /* rgb = fog colour, w = exp fog density (0 = linear fog) */\n"
	"	vec4  fogParams;    /* x = linear fog end, y = minimum ambient, z = emissive strength, w = unused */\n"
	"	ivec4 worldSize;    /* xyz = world dimensions */\n"
	"	ivec4 screen;       /* xy = render size, z = frame index, w = flags */\n"
	"	ivec4 atlas;        /* x = atlas1D shift, y = atlas1D mask, z = atlas count, w = tile size in pixels */\n"
	"	vec4  misc;         /* x = atlas1D V per tile, y = max primary distance, z = GI ray distance, w = pixel angular size */\n"
	"	ivec4 window;       /* xy = window size in pixels (render size may be smaller, see rt-scale), z = entity count, w = emitter count */\n"
	"	vec4  clouds;       /* x = clouds height, y = cloud texture scroll offset, z = shadow strength, w = enabled */\n"
	"};\n"
	"\n"
	"#define FLAG_GI          1\n"
	"#define FLAG_REFLECTIONS 2\n"
	"#define FLAG_SOFT_SHADOWS 4\n"
	"\n"
	"/* Must match struct RTBlockInfo in RayTracer.c */\n"
	"struct BlockInfo {\n"
	"	vec4  minBB;  /* xyz = min bounds, w = draw type */\n"
	"	vec4  maxBB;  /* xyz = max bounds, w = flags */\n"
	"	uvec4 texA;   /* tile ids for faces XMIN, XMAX, ZMIN, ZMAX */\n"
	"	uvec4 texB;   /* tile ids for faces YMIN, YMAX, then unused */\n"
	"	vec4  tint;   /* rgb = colour multiplier, w = 1 if block is full bright */\n"
	"};\n"
	"\n"
	"layout(std430, binding = 1) readonly buffer BlockTable { BlockInfo blocks[]; };\n"
	"\n"
	"layout(binding = 1) uniform usampler3D worldTex;\n"
	"layout(binding = 2) uniform sampler2D atlas0;\n"
	"layout(binding = 3) uniform sampler2D atlas1;\n"
	"layout(binding = 4) uniform sampler2D atlas2;\n"
	"layout(binding = 5) uniform sampler2D atlas3;\n"
	"/* 1 byte per 8x8x8 region of the world: 0 if the region is entirely air, so rays can skip it */\n"
	"layout(binding = 14) uniform usampler3D coarseTex;\n"
	"#define COARSE_SHIFT 3\n"
	"#define COARSE_SIZE  8.0\n"
	"/* The game's cloud texture, for cloud shadows */\n"
	"layout(binding = 15) uniform sampler2D cloudsTex;\n"
	"\n"
	"/* Entity models drawn this frame, recorded as world space quads (must match RTEntity in RayTracer.c) */\n"
	"struct EntityInfo {\n"
	"	vec4  bbMin;\n"
	"	vec4  bbMax;\n"
	"	uvec4 range;  /* x = first quad, y = quad count */\n"
	"};\n"
	"layout(std430, binding = 2) readonly buffer EntityTable { EntityInfo entities[]; };\n"
	"layout(std430, binding = 3) readonly buffer EntityQuads { vec4 quadVerts[]; };\n"
	"/* Light emitting blocks near the camera: xyz = block position, w = block id */\n"
	"layout(std430, binding = 4) readonly buffer EmitterTable { ivec4 emitters[]; };\n"
	"\n"
	"#define DRAW_OPAQUE            0\n"
	"#define DRAW_TRANSPARENT       1\n"
	"#define DRAW_TRANSPARENT_THICK 2\n"
	"#define DRAW_TRANSLUCENT       3\n"
	"#define DRAW_GAS               4\n"
	"#define DRAW_SPRITE            5\n"
	"\n"
	"#define BLOCKFLAG_BLOCKS_LIGHT 1\n"
	"\n"
	"#define FACE_XMIN 0\n"
	"#define FACE_XMAX 1\n"
	"#define FACE_ZMIN 2\n"
	"#define FACE_ZMAX 3\n"
	"#define FACE_YMIN 4\n"
	"#define FACE_YMAX 5\n"
	"\n"
	"#define MAX_DDA_STEPS 1024\n"
	"\n"
	"struct Hit {\n"
	"	vec3  pos;     /* world space hit position */\n"
	"	vec3  normal;  /* geometric normal facing the ray */\n"
	"	vec2  uv;      /* texture coordinates within the tile */\n"
	"	float t;       /* distance along the ray */\n"
	"	uint  block;   /* block id that was hit */\n"
	"	uint  face;    /* FACE_ constant of hit face */\n"
	"	uint  draw;    /* draw type of hit block */\n"
	"};\n"
	"\n"
	"int  drawType(uint block)  { return int(blocks[block].minBB.w); }\n"
	"bool blocksLight(uint block) { return (int(blocks[block].maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) != 0; }\n"
	"bool fullBright(uint block) { return blocks[block].tint.w > 0.5; }\n"
	"\n"
	"uint tileFor(uint block, uint face) {\n"
	"	/* NOTE: NVIDIA's compiler rejects a constant out of range index even in a branch that */\n"
	"	/*  can't be taken, so the index must stay in range for every possible face value */\n"
	"	uvec4 tiles = (face < 4u) ? blocks[block].texA : blocks[block].texB;\n"
	"	return tiles[face & 3u];\n"
	"}\n"
	"\n"
	"uint coarseAt(ivec3 cc) {\n"
	"	return texelFetch(coarseTex, ivec3(cc.x, cc.z, cc.y), 0).r;\n"
	"}\n"
	"\n"
	"uint blockAt(ivec3 p) {\n"
	"	if (any(lessThan(p, ivec3(0))) || any(greaterThanEqual(p, worldSize.xyz))) return 0u;\n"
	"	/* world texture is stored as (x, z, y) so that height is the depth axis */\n"
	"	return texelFetch(worldTex, ivec3(p.x, p.z, p.y), 0).r;\n"
	"}\n"
	"\n"
	"vec4 sampleTile(uint texLoc, vec2 uv, float lod) {\n"
	"	uint idx = texLoc >> uint(atlas.x);\n"
	"	uint row = texLoc &  uint(atlas.y);\n"
	"	/* keep slightly inside the tile, so mipmaps/filtering don't bleed neighbouring tiles */\n"
	"	float pad = 0.5 / float(atlas.w);\n"
	"	uv = clamp(uv, vec2(pad), vec2(1.0 - pad));\n"
	"	vec2 st = vec2(uv.x, (float(row) + uv.y) * misc.x);\n"
	"\n"
	"	if (idx == 0u) return textureLod(atlas0, st, lod);\n"
	"	if (idx == 1u) return textureLod(atlas1, st, lod);\n"
	"	if (idx == 2u) return textureLod(atlas2, st, lod);\n"
	"	return textureLod(atlas3, st, lod);\n"
	"}\n"
	"\n"
	"/* Texture coordinates for a point on the given face, matching Drawer.c orientation */\n"
	"vec2 faceUV(uint face, vec3 local) {\n"
	"	if (face == FACE_XMIN) return vec2(local.z,       1.0 - local.y);\n"
	"	if (face == FACE_XMAX) return vec2(1.0 - local.z, 1.0 - local.y);\n"
	"	if (face == FACE_ZMIN) return vec2(1.0 - local.x, 1.0 - local.y);\n"
	"	if (face == FACE_ZMAX) return vec2(local.x,       1.0 - local.y);\n"
	"	return vec2(local.x, local.z); /* YMIN / YMAX */\n"
	"}\n"
	"\n"
	"/* Whether a texel of the given tile should be treated as solid for alpha tested blocks */\n"
	"bool texelSolid(uint block, uint face, vec2 uv) {\n"
	"	return sampleTile(tileFor(block, face), uv, 0.0).a > 0.5;\n"
	"}\n"
	"\n"
	"/* Intersects the ray with the geometry of one block inside cell c.\n"
	"   tMin/tMax bound the ray segment that lies inside the cell */\n"
	"bool hitCell(ivec3 c, uint block, vec3 ro, vec3 rd, vec3 invRd, float tMin, float tMax, bool shadowRay, bool skipTranslucent, inout Hit h) {\n"
	"	BlockInfo bi = blocks[block];\n"
	"	int  draw = int(bi.minBB.w);\n"
	"	vec3 base = vec3(c);\n"
	"\n"
	"	if (draw == DRAW_GAS) return false;\n"
	"	if (shadowRay && (int(bi.maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) == 0) return false;\n"
	"	if (draw == DRAW_TRANSLUCENT && skipTranslucent) return false;\n"
	"\n"
	"	if (draw == DRAW_SPRITE) {\n"
	"		/* Two crossed quads along the diagonals of the cell */\n"
	"		float bestT = 1e30;\n"
	"		vec2  bestUV = vec2(0.0);\n"
	"		vec3  bestN  = vec3(0.0);\n"
	"		vec3  o = ro - base;\n"
	"\n"
	"		for (int i = 0; i < 2; i++) {\n"
	"			/* plane i = 0: x == z    plane i = 1: x == 1 - z */\n"
	"			vec3 n = (i == 0) ? vec3(1.0, 0.0, -1.0) : vec3(1.0, 0.0, 1.0);\n"
	"			float d = (i == 0) ? 0.0 : 1.0;\n"
	"			float denom = dot(rd, n);\n"
	"			if (abs(denom) < 1e-6) continue;\n"
	"\n"
	"			float t = (d - dot(o, n)) / denom;\n"
	"			if (t < tMin - 1e-4 || t > tMax + 1e-4 || t >= bestT) continue;\n"
	"\n"
	"			vec3 p = o + rd * t;\n"
	"			if (p.y < 0.0 || p.y > 1.0 || p.x < 0.0 || p.x > 1.0 || p.z < 0.0 || p.z > 1.0) continue;\n"
	"\n"
	"			vec2 uv = vec2(p.x, 1.0 - p.y);\n"
	"			if (!texelSolid(block, FACE_XMIN, uv)) continue;\n"
	"\n"
	"			bestT  = t;\n"
	"			bestUV = uv;\n"
	"			bestN  = normalize(n) * ((denom > 0.0) ? -1.0 : 1.0);\n"
	"		}\n"
	"		if (bestT >= 1e30) return false;\n"
	"\n"
	"		h.t = bestT; h.pos = ro + rd * bestT; h.normal = bestN; h.uv = bestUV;\n"
	"		h.block = block; h.face = FACE_XMIN; h.draw = uint(draw);\n"
	"		return true;\n"
	"	}\n"
	"\n"
	"	vec3 bmin = base + bi.minBB.xyz;\n"
	"	vec3 bmax = base + bi.maxBB.xyz;\n"
	"	vec3 t1 = (bmin - ro) * invRd;\n"
	"	vec3 t2 = (bmax - ro) * invRd;\n"
	"	vec3 tn = min(t1, t2);\n"
	"	vec3 tf = max(t1, t2);\n"
	"	float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"	float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"\n"
	"	/* small tolerance, since the DDA's accumulated cell boundaries drift slightly from the exact slab distances */\n"
	"	if (tExit < tEnter || tExit < tMin - 1e-4 || tEnter > tMax + 1e-4) return false;\n"
	"	/* ray starts inside this block - look through it (like backface culling does) */\n"
	"	if (tEnter < 0.0) return false;\n"
	"\n"
	"	vec3 normal; uint face;\n"
	"	if (tEnter == tn.x) {\n"
	"		normal = vec3(rd.x > 0.0 ? -1.0 : 1.0, 0.0, 0.0);\n"
	"		face   = rd.x > 0.0 ? FACE_XMIN : FACE_XMAX;\n"
	"	} else if (tEnter == tn.y) {\n"
	"		normal = vec3(0.0, rd.y > 0.0 ? -1.0 : 1.0, 0.0);\n"
	"		face   = rd.y > 0.0 ? FACE_YMIN : FACE_YMAX;\n"
	"	} else {\n"
	"		normal = vec3(0.0, 0.0, rd.z > 0.0 ? -1.0 : 1.0);\n"
	"		face   = rd.z > 0.0 ? FACE_ZMIN : FACE_ZMAX;\n"
	"	}\n"
	"\n"
	"	/* Faces shared with an identical neighbouring block aren't drawn (e.g. between two water */\n"
	"	/*  blocks, which are slightly lower than a full cell so rays can slip between them) */\n"
	"	if (draw != DRAW_TRANSPARENT_THICK && blockAt(c + ivec3(normal)) == block) return false;\n"
	"\n"
	"	vec3 local = clamp(ro + rd * tEnter - base, 0.0, 1.0);\n"
	"	vec2 uv    = faceUV(face, local);\n"
	"\n"
	"	if (draw == DRAW_TRANSPARENT || draw == DRAW_TRANSPARENT_THICK) {\n"
	"		if (!texelSolid(block, face, uv)) return false;\n"
	"	}\n"
	"\n"
	"	h.t = tEnter; h.pos = ro + rd * tEnter; h.normal = normal; h.uv = uv;\n"
	"	h.block = block; h.face = face; h.draw = uint(draw);\n"
	"	return true;\n"
	"}\n"
	"\n"
	"/* Walks the voxel grid along the ray. Returns true if any block geometry was hit within maxT */\n"
	"bool traceRay(vec3 ro, vec3 rd, float maxT, bool shadowRay, bool skipTranslucent, out Hit h) {\n"
	"	vec3  wsize = vec3(worldSize.xyz);\n"
	"	float tOffset = 0.0;\n"
	"	h.t = -1.0; h.block = 0u;\n"
	"\n"
	"	/* Clip the ray to the world bounds first */\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	if (any(lessThan(ro, vec3(0.0))) || any(greaterThanEqual(ro, wsize))) {\n"
	"		vec3 t1 = (vec3(0.0) - ro) * invRd;\n"
	"		vec3 t2 = (wsize      - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2);\n"
	"		vec3 tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < tEnter || tExit < 0.0 || tEnter > maxT) return false;\n"
	"\n"
	"		tOffset = max(tEnter, 0.0) + 1e-4;\n"
	"		ro     += rd * tOffset;\n"
	"		maxT   -= tOffset;\n"
	"	}\n"
	"\n"
	"	ivec3 c   = ivec3(floor(ro));\n"
	"	c = clamp(c, ivec3(0), worldSize.xyz - 1);\n"
	"	ivec3 stp = ivec3(sign(rd));\n"
	"	vec3  side = vec3(greaterThan(rd, vec3(0.0)));\n"
	"	float t = 0.0;\n"
	"	ivec3 lastCoarse = ivec3(-1);\n"
	"	bool  coarseEmpty = false;\n"
	"\n"
	"	for (int i = 0; i < MAX_DDA_STEPS; i++) {\n"
	"		ivec3 cc = c >> COARSE_SHIFT;\n"
	"		if (cc != lastCoarse) {\n"
	"			lastCoarse  = cc;\n"
	"			coarseEmpty = coarseAt(cc) == 0u;\n"
	"		}\n"
	"\n"
	"		if (coarseEmpty) {\n"
	"			/* Whole 8x8x8 region is air - jump straight to where the ray leaves it */\n"
	"			vec3 cmin = vec3(cc << COARSE_SHIFT);\n"
	"			vec3 tf = max((cmin - ro) * invRd, (cmin + COARSE_SIZE - ro) * invRd);\n"
	"			if (rd.x == 0.0) tf.x = 1e30;\n"
	"			if (rd.y == 0.0) tf.y = 1e30;\n"
	"			if (rd.z == 0.0) tf.z = 1e30;\n"
	"			t = min(min(tf.x, tf.y), tf.z);\n"
	"			if (t > maxT) return false;\n"
	"\n"
	"			ivec3 lo = cc << COARSE_SHIFT;\n"
	"			c = clamp(ivec3(floor(ro + rd * t)), lo, lo + int(COARSE_SIZE) - 1);\n"
	"			/* step the axis that was crossed into the neighbouring region exactly */\n"
	"			if (t == tf.x)      c.x = (stp.x > 0) ? lo.x + int(COARSE_SIZE) : lo.x - 1;\n"
	"			else if (t == tf.y) c.y = (stp.y > 0) ? lo.y + int(COARSE_SIZE) : lo.y - 1;\n"
	"			else                c.z = (stp.z > 0) ? lo.z + int(COARSE_SIZE) : lo.z - 1;\n"
	"\n"
	"			if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"			continue;\n"
	"		}\n"
	"\n"
	"		/* Distance to each of the three cell boundaries in front of the ray. Recomputed from the */\n"
	"		/*  cell coordinates every step, so no floating point drift accumulates between the cell */\n"
	"		/*  walk and the exact slab tests in hitCell (drift caused cracks between blocks) */\n"
	"		vec3 tNext = (vec3(c) + side - ro) * invRd;\n"
	"		if (rd.x == 0.0) tNext.x = 1e30;\n"
	"		if (rd.y == 0.0) tNext.y = 1e30;\n"
	"		if (rd.z == 0.0) tNext.z = 1e30;\n"
	"		float tExit = min(min(tNext.x, tNext.y), tNext.z);\n"
	"		uint  b = blockAt(c);\n"
	"\n"
	"		if (b != 0u) {\n"
	"			if (hitCell(c, b, ro, rd, invRd, t, min(tExit, maxT), shadowRay, skipTranslucent, h)) {\n"
	"				h.t += tOffset;\n"
	"				return true;\n"
	"			}\n"
	"		}\n"
	"\n"
	"		if (tNext.x < tNext.y && tNext.x < tNext.z) {\n"
	"			c.x += stp.x;\n"
	"		} else if (tNext.y < tNext.z) {\n"
	"			c.y += stp.y;\n"
	"		} else {\n"
	"			c.z += stp.z;\n"
	"		}\n"
	"		t = tExit;\n"
	"\n"
	"		if (t > maxT) return false;\n"
	"		if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* Colour of a face when in direct sunlight, following the classic per-face shading */\n"
	"vec3 sunlitColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return sunCol.rgb;\n"
	"	if (n.y < -0.5) return sunYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return sunXSide.rgb;\n"
	"	return sunZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Colour of a face when only lit by the sky */\n"
	"vec3 shadowColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return shadowCol.rgb;\n"
	"	if (n.y < -0.5) return shadowYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return shadowXSide.rgb;\n"
	"	return shadowZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Moller-Trumbore ray/triangle test, both sides */\n"
	"bool hitTriangle(vec3 ro, vec3 rd, vec3 a, vec3 b, vec3 c, float maxT) {\n"
	"	vec3 e1 = b - a, e2 = c - a;\n"
	"	vec3 pv = cross(rd, e2);\n"
	"	float det = dot(e1, pv);\n"
	"	if (abs(det) < 1e-7) return false;\n"
	"	float inv = 1.0 / det;\n"
	"	vec3 tv = ro - a;\n"
	"	float u = dot(tv, pv) * inv;\n"
	"	if (u < 0.0 || u > 1.0) return false;\n"
	"	vec3 qv = cross(tv, e1);\n"
	"	float v = dot(rd, qv) * inv;\n"
	"	if (v < 0.0 || u + v > 1.0) return false;\n"
	"	float t = dot(e2, qv) * inv;\n"
	"	return t > 1e-3 && t < maxT;\n"
	"}\n"
	"\n"
	"/* Whether the ray hits any entity (player) model recorded this frame */\n"
	"bool hitEntities(vec3 ro, vec3 rd, float maxT) {\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	for (int i = 0; i < window.z; i++) {\n"
	"		EntityInfo e = entities[i];\n"
	"		vec3 t1 = (e.bbMin.xyz - ro) * invRd;\n"
	"		vec3 t2 = (e.bbMax.xyz - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2), tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < max(tEnter, 0.0) || tEnter > maxT) continue;\n"
	"\n"
	"		uint first = e.range.x, count = e.range.y;\n"
	"		for (uint q = 0u; q < count; q++) {\n"
	"			uint b = (first + q) * 4u;\n"
	"			vec3 v0 = quadVerts[b].xyz, v1 = quadVerts[b + 1u].xyz;\n"
	"			vec3 v2 = quadVerts[b + 2u].xyz, v3 = quadVerts[b + 3u].xyz;\n"
	"			if (hitTriangle(ro, rd, v0, v1, v2, maxT) || hitTriangle(ro, rd, v0, v2, v3, maxT)) return true;\n"
	"		}\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* How much sunlight gets through the clouds along L from p (1 = no cloud) */\n"
	"float cloudShadow(vec3 p, vec3 L) {\n"
	"	if (clouds.w < 0.5 || L.y <= 0.0 || p.y >= clouds.x) return 1.0;\n"
	"	float t  = (clouds.x - p.y) / L.y;\n"
	"	vec2  xz = p.xz + L.xz * t;\n"
	"	/* same mapping as the cloud layer: 2048 blocks per texture repeat, scrolling along U */\n"
	"	vec2  uv = fract(vec2(xz.x / 2048.0 + clouds.y, xz.y / 2048.0));\n"
	"	float a  = textureLod(cloudsTex, uv, 0.0).a;\n"
	"	return 1.0 - a * clouds.z;\n"
	"}\n"
	"\n"
	"/* Direct sunlight contribution for a surface point, tracing a shadow ray towards the sun */\n"
	"vec3 directSun(vec3 p, vec3 n, vec3 L) {\n"
	"	float ndl = dot(n, L);\n"
	"	if (ndl <= 0.0) return vec3(0.0);\n"
	"\n"
	"	Hit sh;\n"
	"	if (traceRay(p, L, 512.0, true, false, sh)) return vec3(0.0);\n"
	"	if (window.z > 0 && hitEntities(p, L, 64.0)) return vec3(0.0);\n"
	"\n"
	"	/* Normalise so that an upward facing face receives the full classic sun colour */\n"
	"	float f = clamp(ndl / max(L.y, 0.2), 0.0, 1.0) * cloudShadow(p, L);\n"
	"	return max(sunlitColour(n) - shadowColour(n), vec3(0.0)) * f;\n"
	"}\n"
	"\n"
	"/* Random number helpers */\n"
	"uint pcgHash(uint v) {\n"
	"	uint state = v * 747796405u + 2891336453u;\n"
	"	uint word  = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;\n"
	"	return (word >> 22u) ^ word;\n"
	"}\n"
	"\n"
	"float rand(inout uint seed) {\n"
	"	seed = pcgHash(seed);\n"
	"	return float(seed) * (1.0 / 4294967296.0);\n"
	"}\n"
	"\n"
	"/* Cosine weighted direction in the hemisphere around n */\n"
	"vec3 cosineSample(vec3 n, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float sr2 = sqrt(r2);\n"
	"	vec3 t = abs(n.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, n));\n"
	"	vec3 v = cross(n, u);\n"
	"	return normalize(u * (cos(phi) * sr2) + v * (sin(phi) * sr2) + n * sqrt(max(0.0, 1.0 - r2)));\n"
	"}\n"
	"\n"
	"/* Random direction inside a cone around dir, tan of half angle = tanRadius */\n"
	"vec3 coneSample(vec3 dir, float tanRadius, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float r   = tanRadius * sqrt(r2);\n"
	"	vec3 t = abs(dir.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, dir));\n"
	"	vec3 v = cross(dir, u);\n"
	"	return normalize(dir + u * (cos(phi) * r) + v * (sin(phi) * r));\n"
	"}\n"
	"\n"
	"/* Light received from emitting blocks (lava, lamps...) by explicitly sampling one of them.\n"
	"   Picks an emitter with probability proportional to 1/distance^2, then traces a ray to it.\n"
	"   Noisy per frame, but the temporal accumulation and blur average it out. */\n"
	"vec3 emitterLight(vec3 p, vec3 n, inout uint seed) {\n"
	"	int count = window.w;\n"
	"	if (count == 0) return vec3(0.0);\n"
	"\n"
	"	float wsum = 0.0, chosenW = 0.0;\n"
	"	int chosen = -1;\n"
	"	for (int i = 0; i < count; i++) {\n"
	"		vec3 d = vec3(emitters[i].xyz) + 0.5 - p;\n"
	"		float d2 = dot(d, d);\n"
	"		if (d2 > 32.0 * 32.0 || dot(d, n) <= 0.0) continue;\n"
	"\n"
	"		float w = 1.0 / max(d2, 1.0);\n"
	"		wsum += w;\n"
	"		if (rand(seed) * wsum < w) { chosen = i; chosenW = w; }\n"
	"	}\n"
	"	if (chosen < 0) return vec3(0.0);\n"
	"\n"
	"	vec3  d    = vec3(emitters[chosen].xyz) + 0.5 - p;\n"
	"	float dist = length(d);\n"
	"	vec3  dir  = d / dist;\n"
	"	Hit eh;\n"
	"	if (!traceRay(p, dir, dist + 1.0, false, true, eh)) return vec3(0.0);\n"
	"	/* must have reached the emitter itself, not something in between */\n"
	"	if (ivec3(floor(eh.pos - eh.normal * 0.5)) != emitters[chosen].xyz) return vec3(0.0);\n"
	"\n"
	"	vec3  Le   = sampleTile(tileFor(eh.block, eh.face), eh.uv, 4.0).rgb * blocks[eh.block].tint.rgb * fogParams.z;\n"
	"	float cosR = max(dot(n, dir), 0.0);\n"
	"	float cosE = max(dot(-dir, eh.normal), 0.0);\n"
	"	float falloff = 1.0 / max(dist * dist, 1.0);\n"
	"	return Le * cosR * cosE * falloff * (wsum / chosenW) / 3.14159265;\n"
	"}\n"
	"\n"
	"/* Primary ray pass: traces one camera ray per pixel, then shades the hit with\n"
	"   a sun shadow ray, one diffuse bounce (global illumination), and a mirror\n"
	"   reflection ray for translucent blocks such as water.\n"
	"   Outputs a G-buffer plus separate lighting terms for the denoiser. */\n"
	"layout(local_size_x = 8, local_size_y = 8) in;\n"
	"\n"
	"layout(rgba32f, binding = 0) uniform writeonly image2D gbufImg;     /* xyz = hit position, w = distance (-1 = miss) */\n"
	"layout(rgba32f, binding = 1) uniform writeonly image2D normalImg;   /* xyz = normal, w = block id */\n"
	"layout(rgba16f, binding = 2) uniform writeonly image2D albedoImg;   /* rgb = albedo, w = distance to water surface (0 = none) */\n"
	"layout(rgba16f, binding = 3) uniform writeonly image2D directImg;   /* rgb = direct + ambient floor */\n"
	"layout(rgba16f, binding = 4) uniform writeonly image2D indirectImg; /* rgb = one bounce / sky sample (noisy) */\n"
	"layout(rgba16f, binding = 5) uniform writeonly image2D waterImg;    /* rgb = premultiplied water colour + reflection, a = alpha */\n"
	"\n"
	"/* Approximate mip level so distant textures don't alias */\n"
	"float lodFor(float dist) {\n"
	"	float texelsPerPixel = dist * misc.w * float(atlas.w);\n"
	"	return max(0.0, log2(max(texelsPerPixel, 1e-4)));\n"
	"}\n"
	"\n"
	"vec3 lightingNormal(Hit h) {\n"
	"	/* sprites are shaded like the top of a block, so plants aren't dark */\n"
	"	return (h.draw == uint(DRAW_SPRITE)) ? vec3(0.0, 1.0, 0.0) : h.normal;\n"
	"}\n"
	"\n"
	"vec3 albedoOf(Hit h, float lod) {\n"
	"	return sampleTile(tileFor(h.block, h.face), h.uv, lod).rgb * blocks[h.block].tint.rgb;\n"
	"}\n"
	"\n"
	"/* Simple shading for secondary hits: sun + ambient floor (+ emissive), no further bounces */\n"
	"vec3 secondaryRadiance(Hit h, vec3 L, float minAmb, bool includeEmissive) {\n"
	"	vec3 n    = lightingNormal(h);\n"
	"	vec3 alb  = albedoOf(h, 2.0);\n"
	"	/* emitters are sampled explicitly by emitterLight(), so bounce rays don't count them again */\n"
	"	if (fullBright(h.block)) return includeEmissive ? alb * fogParams.z : vec3(0.0);\n"
	"\n"
	"	vec3 p    = h.pos + h.normal * 2e-3;\n"
	"	vec3 light = directSun(p, n, L) + shadowColour(n) * minAmb;\n"
	"	return alb * light;\n"
	"}\n"
	"\n"
	"void main() {\n"
	"	ivec2 px = ivec2(gl_GlobalInvocationID.xy);\n"
	"	if (px.x >= screen.x || px.y >= screen.y) return;\n"
	"\n"
	"	int  flags  = screen.w;\n"
	"	uint seed   = uint(px.x + px.y * screen.x) * 9781u + uint(screen.z) * 6271u + 1u;\n"
	"	float minAmb = fogParams.y;\n"
	"\n"
	"	/* Camera ray through the pixel centre */\n"
	"	vec2 ndc = (vec2(px) + 0.5) / vec2(screen.xy) * 2.0 - 1.0;\n"
	"	vec4 pNear = invViewProj * vec4(ndc, -1.0, 1.0);\n"
	"	vec4 pFar  = invViewProj * vec4(ndc,  1.0, 1.0);\n"
	"	pNear.xyz /= pNear.w;\n"
	"	pFar.xyz  /= pFar.w;\n"
	"	vec3 ro = pNear.xyz;\n"
	"	vec3 rd = normalize(pFar.xyz - pNear.xyz);\n"
	"\n"
	"	vec3 L = sunDir.xyz;\n"
	"	if ((flags & FLAG_SOFT_SHADOWS) != 0) L = coneSample(sunDir.xyz, sunDir.w, seed);\n"
	"\n"
	"	Hit h;\n"
	"	bool  hit    = traceRay(ro, rd, misc.y, false, false, h);\n"
	"	float waterT = 0.0;\n"
	"	vec4  water  = vec4(0.0);\n"
	"\n"
	"	if (hit && h.draw == uint(DRAW_TRANSLUCENT)) {\n"
	"		/* Water/ice is a translucent layer blended over whatever is behind it in a second */\n"
	"		/*  composite pass (like the rasteriser draws it after entities), so the surface */\n"
	"		/*  behind it becomes the primary hit for lighting, depth and denoising */\n"
	"		vec4  wtex  = sampleTile(tileFor(h.block, h.face), h.uv, lodFor(h.t));\n"
	"		vec3  wn    = h.normal;\n"
	"		vec3  wp    = h.pos + wn * 2e-3;\n"
	"		vec3  light = directSun(wp, wn, L) + shadowColour(wn);\n"
	"		vec3  wcol  = wtex.rgb * blocks[h.block].tint.rgb * light * wtex.a;\n"
	"\n"
	"		if ((flags & FLAG_REFLECTIONS) != 0) {\n"
	"			vec3  R = reflect(rd, wn);\n"
	"			float cosT = clamp(dot(-rd, wn), 0.0, 1.0);\n"
	"			float F = 0.04 + 0.96 * pow(1.0 - cosT, 5.0);\n"
	"			Hit rh;\n"
	"			vec3 refl = skyCol.rgb;\n"
	"			if (traceRay(wp, R, misc.y, false, false, rh)) {\n"
	"				refl = secondaryRadiance(rh, sunDir.xyz, minAmb, true) + albedoOf(rh, 2.0) * shadowColour(lightingNormal(rh)) * (1.0 - minAmb);\n"
	"			}\n"
	"			wcol += refl * F;\n"
	"		}\n"
	"		waterT = h.t;\n"
	"		water  = vec4(wcol, wtex.a);\n"
	"\n"
	"		hit = traceRay(h.pos + rd * 1e-3, rd, misc.y, false, true, h);\n"
	"	}\n"
	"\n"
	"	if (!hit) {\n"
	"		imageStore(gbufImg,     px, vec4(0.0, 0.0, 0.0, -1.0));\n"
	"		imageStore(normalImg,   px, vec4(0.0));\n"
	"		imageStore(albedoImg,   px, vec4(0.0, 0.0, 0.0, waterT));\n"
	"		imageStore(directImg,   px, vec4(0.0));\n"
	"		imageStore(indirectImg, px, vec4(0.0));\n"
	"		imageStore(waterImg,    px, water);\n"
	"		return;\n"
	"	}\n"
	"\n"
	"	vec3  n     = lightingNormal(h);\n"
	"	vec3  pOff  = h.pos + h.normal * 2e-3;\n"
	"	vec4  tex   = sampleTile(tileFor(h.block, h.face), h.uv, lodFor(h.t));\n"
	"	vec3  albedo = tex.rgb * blocks[h.block].tint.rgb;\n"
	"	vec3  direct, indirect;\n"
	"\n"
	"	if (fullBright(h.block)) {\n"
	"		/* Lava, glowing blocks: show the texture at full brightness */\n"
	"		direct   = vec3(1.0);\n"
	"		indirect = vec3(0.0);\n"
	"	} else {\n"
	"		direct = directSun(pOff, n, L) + shadowColour(n) * minAmb;\n"
	"\n"
	"		if ((flags & FLAG_GI) != 0) {\n"
	"			vec3 d = cosineSample(n, seed);\n"
	"			Hit gh;\n"
	"			if (traceRay(pOff, d, misc.z, false, false, gh)) {\n"
	"				indirect = secondaryRadiance(gh, sunDir.xyz, minAmb, false);\n"
	"			} else {\n"
	"				/* escaped to the sky: classic shadow colour is the sky ambient */\n"
	"				indirect = shadowColour(n) * (1.0 - minAmb);\n"
	"			}\n"
	"			indirect += emitterLight(pOff, n, seed);\n"
	"		} else {\n"
	"			indirect = shadowColour(n) * (1.0 - minAmb);\n"
	"		}\n"
	"	}\n"
	"\n"
	"	imageStore(gbufImg,     px, vec4(h.pos, h.t));\n"
	"	imageStore(normalImg,   px, vec4(h.normal, float(h.block)));\n"
	"	imageStore(albedoImg,   px, vec4(albedo, waterT));\n"
	"	imageStore(directImg,   px, vec4(direct, 1.0));\n"
	"	imageStore(indirectImg, px, vec4(indirect, 1.0));\n"
	"	imageStore(waterImg,    px, water);\n"
	"}\n"
	"\n";

static const char* const RT_TEMPORAL_SRC =
	"#version 430\n"
	"/* Shared code for the ClassiCube GPU voxel path tracer (see src/RayTracer.c)\n"
	"   The world is traced directly as a voxel grid using a 3D DDA walk, so no\n"
	"   acceleration structure has to be built or maintained on block changes.\n"
	"   Copyright 2014-2025 ClassiCube | Licensed under BSD-3 */\n"
	"\n"
	"/* Must match struct RTParams in RayTracer.c (std140 layout, vec4/mat4 only) */\n"
	"layout(std140, binding = 0) uniform Params {\n"
	"	mat4  invViewProj;  /* clip space -> world space */\n"
	"	mat4  viewProj;     /* world space -> clip space (current frame) */\n"
	"	mat4  prevViewProj; /* world space -> clip space (previous frame) */\n"
	"	mat4  view;         /* world space -> eye space */\n"
	"	vec4  camPos;       /* xyz = camera position, w = time in seconds */\n"
	"	vec4  sunDir;       /* xyz = direction towards the sun, w = tan(sun angular radius) */\n"
	"	vec4  sunCol, sunXSide, sunZSide, sunYMin;\n"
	"	vec4  shadowCol, shadowXSide, shadowZSide, shadowYMin;\n"
	"	vec4  skyCol;       /* rgb = colour seen by rays that escape the world */\n"
	"	vec4  fogCol;       /* rgb = fog colour, w = exp fog density (0 = linear fog) */\n"
	"	vec4  fogParams;    /* x = linear fog end, y = minimum ambient, z = emissive strength, w = unused */\n"
	"	ivec4 worldSize;    /* xyz = world dimensions */\n"
	"	ivec4 screen;       /* xy = render size, z = frame index, w = flags */\n"
	"	ivec4 atlas;        /* x = atlas1D shift, y = atlas1D mask, z = atlas count, w = tile size in pixels */\n"
	"	vec4  misc;         /* x = atlas1D V per tile, y = max primary distance, z = GI ray distance, w = pixel angular size */\n"
	"	ivec4 window;       /* xy = window size in pixels (render size may be smaller, see rt-scale), z = entity count, w = emitter count */\n"
	"	vec4  clouds;       /* x = clouds height, y = cloud texture scroll offset, z = shadow strength, w = enabled */\n"
	"};\n"
	"\n"
	"#define FLAG_GI          1\n"
	"#define FLAG_REFLECTIONS 2\n"
	"#define FLAG_SOFT_SHADOWS 4\n"
	"\n"
	"/* Must match struct RTBlockInfo in RayTracer.c */\n"
	"struct BlockInfo {\n"
	"	vec4  minBB;  /* xyz = min bounds, w = draw type */\n"
	"	vec4  maxBB;  /* xyz = max bounds, w = flags */\n"
	"	uvec4 texA;   /* tile ids for faces XMIN, XMAX, ZMIN, ZMAX */\n"
	"	uvec4 texB;   /* tile ids for faces YMIN, YMAX, then unused */\n"
	"	vec4  tint;   /* rgb = colour multiplier, w = 1 if block is full bright */\n"
	"};\n"
	"\n"
	"layout(std430, binding = 1) readonly buffer BlockTable { BlockInfo blocks[]; };\n"
	"\n"
	"layout(binding = 1) uniform usampler3D worldTex;\n"
	"layout(binding = 2) uniform sampler2D atlas0;\n"
	"layout(binding = 3) uniform sampler2D atlas1;\n"
	"layout(binding = 4) uniform sampler2D atlas2;\n"
	"layout(binding = 5) uniform sampler2D atlas3;\n"
	"/* 1 byte per 8x8x8 region of the world: 0 if the region is entirely air, so rays can skip it */\n"
	"layout(binding = 14) uniform usampler3D coarseTex;\n"
	"#define COARSE_SHIFT 3\n"
	"#define COARSE_SIZE  8.0\n"
	"/* The game's cloud texture, for cloud shadows */\n"
	"layout(binding = 15) uniform sampler2D cloudsTex;\n"
	"\n"
	"/* Entity models drawn this frame, recorded as world space quads (must match RTEntity in RayTracer.c) */\n"
	"struct EntityInfo {\n"
	"	vec4  bbMin;\n"
	"	vec4  bbMax;\n"
	"	uvec4 range;  /* x = first quad, y = quad count */\n"
	"};\n"
	"layout(std430, binding = 2) readonly buffer EntityTable { EntityInfo entities[]; };\n"
	"layout(std430, binding = 3) readonly buffer EntityQuads { vec4 quadVerts[]; };\n"
	"/* Light emitting blocks near the camera: xyz = block position, w = block id */\n"
	"layout(std430, binding = 4) readonly buffer EmitterTable { ivec4 emitters[]; };\n"
	"\n"
	"#define DRAW_OPAQUE            0\n"
	"#define DRAW_TRANSPARENT       1\n"
	"#define DRAW_TRANSPARENT_THICK 2\n"
	"#define DRAW_TRANSLUCENT       3\n"
	"#define DRAW_GAS               4\n"
	"#define DRAW_SPRITE            5\n"
	"\n"
	"#define BLOCKFLAG_BLOCKS_LIGHT 1\n"
	"\n"
	"#define FACE_XMIN 0\n"
	"#define FACE_XMAX 1\n"
	"#define FACE_ZMIN 2\n"
	"#define FACE_ZMAX 3\n"
	"#define FACE_YMIN 4\n"
	"#define FACE_YMAX 5\n"
	"\n"
	"#define MAX_DDA_STEPS 1024\n"
	"\n"
	"struct Hit {\n"
	"	vec3  pos;     /* world space hit position */\n"
	"	vec3  normal;  /* geometric normal facing the ray */\n"
	"	vec2  uv;      /* texture coordinates within the tile */\n"
	"	float t;       /* distance along the ray */\n"
	"	uint  block;   /* block id that was hit */\n"
	"	uint  face;    /* FACE_ constant of hit face */\n"
	"	uint  draw;    /* draw type of hit block */\n"
	"};\n"
	"\n"
	"int  drawType(uint block)  { return int(blocks[block].minBB.w); }\n"
	"bool blocksLight(uint block) { return (int(blocks[block].maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) != 0; }\n"
	"bool fullBright(uint block) { return blocks[block].tint.w > 0.5; }\n"
	"\n"
	"uint tileFor(uint block, uint face) {\n"
	"	/* NOTE: NVIDIA's compiler rejects a constant out of range index even in a branch that */\n"
	"	/*  can't be taken, so the index must stay in range for every possible face value */\n"
	"	uvec4 tiles = (face < 4u) ? blocks[block].texA : blocks[block].texB;\n"
	"	return tiles[face & 3u];\n"
	"}\n"
	"\n"
	"uint coarseAt(ivec3 cc) {\n"
	"	return texelFetch(coarseTex, ivec3(cc.x, cc.z, cc.y), 0).r;\n"
	"}\n"
	"\n"
	"uint blockAt(ivec3 p) {\n"
	"	if (any(lessThan(p, ivec3(0))) || any(greaterThanEqual(p, worldSize.xyz))) return 0u;\n"
	"	/* world texture is stored as (x, z, y) so that height is the depth axis */\n"
	"	return texelFetch(worldTex, ivec3(p.x, p.z, p.y), 0).r;\n"
	"}\n"
	"\n"
	"vec4 sampleTile(uint texLoc, vec2 uv, float lod) {\n"
	"	uint idx = texLoc >> uint(atlas.x);\n"
	"	uint row = texLoc &  uint(atlas.y);\n"
	"	/* keep slightly inside the tile, so mipmaps/filtering don't bleed neighbouring tiles */\n"
	"	float pad = 0.5 / float(atlas.w);\n"
	"	uv = clamp(uv, vec2(pad), vec2(1.0 - pad));\n"
	"	vec2 st = vec2(uv.x, (float(row) + uv.y) * misc.x);\n"
	"\n"
	"	if (idx == 0u) return textureLod(atlas0, st, lod);\n"
	"	if (idx == 1u) return textureLod(atlas1, st, lod);\n"
	"	if (idx == 2u) return textureLod(atlas2, st, lod);\n"
	"	return textureLod(atlas3, st, lod);\n"
	"}\n"
	"\n"
	"/* Texture coordinates for a point on the given face, matching Drawer.c orientation */\n"
	"vec2 faceUV(uint face, vec3 local) {\n"
	"	if (face == FACE_XMIN) return vec2(local.z,       1.0 - local.y);\n"
	"	if (face == FACE_XMAX) return vec2(1.0 - local.z, 1.0 - local.y);\n"
	"	if (face == FACE_ZMIN) return vec2(1.0 - local.x, 1.0 - local.y);\n"
	"	if (face == FACE_ZMAX) return vec2(local.x,       1.0 - local.y);\n"
	"	return vec2(local.x, local.z); /* YMIN / YMAX */\n"
	"}\n"
	"\n"
	"/* Whether a texel of the given tile should be treated as solid for alpha tested blocks */\n"
	"bool texelSolid(uint block, uint face, vec2 uv) {\n"
	"	return sampleTile(tileFor(block, face), uv, 0.0).a > 0.5;\n"
	"}\n"
	"\n"
	"/* Intersects the ray with the geometry of one block inside cell c.\n"
	"   tMin/tMax bound the ray segment that lies inside the cell */\n"
	"bool hitCell(ivec3 c, uint block, vec3 ro, vec3 rd, vec3 invRd, float tMin, float tMax, bool shadowRay, bool skipTranslucent, inout Hit h) {\n"
	"	BlockInfo bi = blocks[block];\n"
	"	int  draw = int(bi.minBB.w);\n"
	"	vec3 base = vec3(c);\n"
	"\n"
	"	if (draw == DRAW_GAS) return false;\n"
	"	if (shadowRay && (int(bi.maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) == 0) return false;\n"
	"	if (draw == DRAW_TRANSLUCENT && skipTranslucent) return false;\n"
	"\n"
	"	if (draw == DRAW_SPRITE) {\n"
	"		/* Two crossed quads along the diagonals of the cell */\n"
	"		float bestT = 1e30;\n"
	"		vec2  bestUV = vec2(0.0);\n"
	"		vec3  bestN  = vec3(0.0);\n"
	"		vec3  o = ro - base;\n"
	"\n"
	"		for (int i = 0; i < 2; i++) {\n"
	"			/* plane i = 0: x == z    plane i = 1: x == 1 - z */\n"
	"			vec3 n = (i == 0) ? vec3(1.0, 0.0, -1.0) : vec3(1.0, 0.0, 1.0);\n"
	"			float d = (i == 0) ? 0.0 : 1.0;\n"
	"			float denom = dot(rd, n);\n"
	"			if (abs(denom) < 1e-6) continue;\n"
	"\n"
	"			float t = (d - dot(o, n)) / denom;\n"
	"			if (t < tMin - 1e-4 || t > tMax + 1e-4 || t >= bestT) continue;\n"
	"\n"
	"			vec3 p = o + rd * t;\n"
	"			if (p.y < 0.0 || p.y > 1.0 || p.x < 0.0 || p.x > 1.0 || p.z < 0.0 || p.z > 1.0) continue;\n"
	"\n"
	"			vec2 uv = vec2(p.x, 1.0 - p.y);\n"
	"			if (!texelSolid(block, FACE_XMIN, uv)) continue;\n"
	"\n"
	"			bestT  = t;\n"
	"			bestUV = uv;\n"
	"			bestN  = normalize(n) * ((denom > 0.0) ? -1.0 : 1.0);\n"
	"		}\n"
	"		if (bestT >= 1e30) return false;\n"
	"\n"
	"		h.t = bestT; h.pos = ro + rd * bestT; h.normal = bestN; h.uv = bestUV;\n"
	"		h.block = block; h.face = FACE_XMIN; h.draw = uint(draw);\n"
	"		return true;\n"
	"	}\n"
	"\n"
	"	vec3 bmin = base + bi.minBB.xyz;\n"
	"	vec3 bmax = base + bi.maxBB.xyz;\n"
	"	vec3 t1 = (bmin - ro) * invRd;\n"
	"	vec3 t2 = (bmax - ro) * invRd;\n"
	"	vec3 tn = min(t1, t2);\n"
	"	vec3 tf = max(t1, t2);\n"
	"	float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"	float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"\n"
	"	/* small tolerance, since the DDA's accumulated cell boundaries drift slightly from the exact slab distances */\n"
	"	if (tExit < tEnter || tExit < tMin - 1e-4 || tEnter > tMax + 1e-4) return false;\n"
	"	/* ray starts inside this block - look through it (like backface culling does) */\n"
	"	if (tEnter < 0.0) return false;\n"
	"\n"
	"	vec3 normal; uint face;\n"
	"	if (tEnter == tn.x) {\n"
	"		normal = vec3(rd.x > 0.0 ? -1.0 : 1.0, 0.0, 0.0);\n"
	"		face   = rd.x > 0.0 ? FACE_XMIN : FACE_XMAX;\n"
	"	} else if (tEnter == tn.y) {\n"
	"		normal = vec3(0.0, rd.y > 0.0 ? -1.0 : 1.0, 0.0);\n"
	"		face   = rd.y > 0.0 ? FACE_YMIN : FACE_YMAX;\n"
	"	} else {\n"
	"		normal = vec3(0.0, 0.0, rd.z > 0.0 ? -1.0 : 1.0);\n"
	"		face   = rd.z > 0.0 ? FACE_ZMIN : FACE_ZMAX;\n"
	"	}\n"
	"\n"
	"	/* Faces shared with an identical neighbouring block aren't drawn (e.g. between two water */\n"
	"	/*  blocks, which are slightly lower than a full cell so rays can slip between them) */\n"
	"	if (draw != DRAW_TRANSPARENT_THICK && blockAt(c + ivec3(normal)) == block) return false;\n"
	"\n"
	"	vec3 local = clamp(ro + rd * tEnter - base, 0.0, 1.0);\n"
	"	vec2 uv    = faceUV(face, local);\n"
	"\n"
	"	if (draw == DRAW_TRANSPARENT || draw == DRAW_TRANSPARENT_THICK) {\n"
	"		if (!texelSolid(block, face, uv)) return false;\n"
	"	}\n"
	"\n"
	"	h.t = tEnter; h.pos = ro + rd * tEnter; h.normal = normal; h.uv = uv;\n"
	"	h.block = block; h.face = face; h.draw = uint(draw);\n"
	"	return true;\n"
	"}\n"
	"\n"
	"/* Walks the voxel grid along the ray. Returns true if any block geometry was hit within maxT */\n"
	"bool traceRay(vec3 ro, vec3 rd, float maxT, bool shadowRay, bool skipTranslucent, out Hit h) {\n"
	"	vec3  wsize = vec3(worldSize.xyz);\n"
	"	float tOffset = 0.0;\n"
	"	h.t = -1.0; h.block = 0u;\n"
	"\n"
	"	/* Clip the ray to the world bounds first */\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	if (any(lessThan(ro, vec3(0.0))) || any(greaterThanEqual(ro, wsize))) {\n"
	"		vec3 t1 = (vec3(0.0) - ro) * invRd;\n"
	"		vec3 t2 = (wsize      - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2);\n"
	"		vec3 tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < tEnter || tExit < 0.0 || tEnter > maxT) return false;\n"
	"\n"
	"		tOffset = max(tEnter, 0.0) + 1e-4;\n"
	"		ro     += rd * tOffset;\n"
	"		maxT   -= tOffset;\n"
	"	}\n"
	"\n"
	"	ivec3 c   = ivec3(floor(ro));\n"
	"	c = clamp(c, ivec3(0), worldSize.xyz - 1);\n"
	"	ivec3 stp = ivec3(sign(rd));\n"
	"	vec3  side = vec3(greaterThan(rd, vec3(0.0)));\n"
	"	float t = 0.0;\n"
	"	ivec3 lastCoarse = ivec3(-1);\n"
	"	bool  coarseEmpty = false;\n"
	"\n"
	"	for (int i = 0; i < MAX_DDA_STEPS; i++) {\n"
	"		ivec3 cc = c >> COARSE_SHIFT;\n"
	"		if (cc != lastCoarse) {\n"
	"			lastCoarse  = cc;\n"
	"			coarseEmpty = coarseAt(cc) == 0u;\n"
	"		}\n"
	"\n"
	"		if (coarseEmpty) {\n"
	"			/* Whole 8x8x8 region is air - jump straight to where the ray leaves it */\n"
	"			vec3 cmin = vec3(cc << COARSE_SHIFT);\n"
	"			vec3 tf = max((cmin - ro) * invRd, (cmin + COARSE_SIZE - ro) * invRd);\n"
	"			if (rd.x == 0.0) tf.x = 1e30;\n"
	"			if (rd.y == 0.0) tf.y = 1e30;\n"
	"			if (rd.z == 0.0) tf.z = 1e30;\n"
	"			t = min(min(tf.x, tf.y), tf.z);\n"
	"			if (t > maxT) return false;\n"
	"\n"
	"			ivec3 lo = cc << COARSE_SHIFT;\n"
	"			c = clamp(ivec3(floor(ro + rd * t)), lo, lo + int(COARSE_SIZE) - 1);\n"
	"			/* step the axis that was crossed into the neighbouring region exactly */\n"
	"			if (t == tf.x)      c.x = (stp.x > 0) ? lo.x + int(COARSE_SIZE) : lo.x - 1;\n"
	"			else if (t == tf.y) c.y = (stp.y > 0) ? lo.y + int(COARSE_SIZE) : lo.y - 1;\n"
	"			else                c.z = (stp.z > 0) ? lo.z + int(COARSE_SIZE) : lo.z - 1;\n"
	"\n"
	"			if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"			continue;\n"
	"		}\n"
	"\n"
	"		/* Distance to each of the three cell boundaries in front of the ray. Recomputed from the */\n"
	"		/*  cell coordinates every step, so no floating point drift accumulates between the cell */\n"
	"		/*  walk and the exact slab tests in hitCell (drift caused cracks between blocks) */\n"
	"		vec3 tNext = (vec3(c) + side - ro) * invRd;\n"
	"		if (rd.x == 0.0) tNext.x = 1e30;\n"
	"		if (rd.y == 0.0) tNext.y = 1e30;\n"
	"		if (rd.z == 0.0) tNext.z = 1e30;\n"
	"		float tExit = min(min(tNext.x, tNext.y), tNext.z);\n"
	"		uint  b = blockAt(c);\n"
	"\n"
	"		if (b != 0u) {\n"
	"			if (hitCell(c, b, ro, rd, invRd, t, min(tExit, maxT), shadowRay, skipTranslucent, h)) {\n"
	"				h.t += tOffset;\n"
	"				return true;\n"
	"			}\n"
	"		}\n"
	"\n"
	"		if (tNext.x < tNext.y && tNext.x < tNext.z) {\n"
	"			c.x += stp.x;\n"
	"		} else if (tNext.y < tNext.z) {\n"
	"			c.y += stp.y;\n"
	"		} else {\n"
	"			c.z += stp.z;\n"
	"		}\n"
	"		t = tExit;\n"
	"\n"
	"		if (t > maxT) return false;\n"
	"		if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* Colour of a face when in direct sunlight, following the classic per-face shading */\n"
	"vec3 sunlitColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return sunCol.rgb;\n"
	"	if (n.y < -0.5) return sunYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return sunXSide.rgb;\n"
	"	return sunZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Colour of a face when only lit by the sky */\n"
	"vec3 shadowColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return shadowCol.rgb;\n"
	"	if (n.y < -0.5) return shadowYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return shadowXSide.rgb;\n"
	"	return shadowZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Moller-Trumbore ray/triangle test, both sides */\n"
	"bool hitTriangle(vec3 ro, vec3 rd, vec3 a, vec3 b, vec3 c, float maxT) {\n"
	"	vec3 e1 = b - a, e2 = c - a;\n"
	"	vec3 pv = cross(rd, e2);\n"
	"	float det = dot(e1, pv);\n"
	"	if (abs(det) < 1e-7) return false;\n"
	"	float inv = 1.0 / det;\n"
	"	vec3 tv = ro - a;\n"
	"	float u = dot(tv, pv) * inv;\n"
	"	if (u < 0.0 || u > 1.0) return false;\n"
	"	vec3 qv = cross(tv, e1);\n"
	"	float v = dot(rd, qv) * inv;\n"
	"	if (v < 0.0 || u + v > 1.0) return false;\n"
	"	float t = dot(e2, qv) * inv;\n"
	"	return t > 1e-3 && t < maxT;\n"
	"}\n"
	"\n"
	"/* Whether the ray hits any entity (player) model recorded this frame */\n"
	"bool hitEntities(vec3 ro, vec3 rd, float maxT) {\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	for (int i = 0; i < window.z; i++) {\n"
	"		EntityInfo e = entities[i];\n"
	"		vec3 t1 = (e.bbMin.xyz - ro) * invRd;\n"
	"		vec3 t2 = (e.bbMax.xyz - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2), tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < max(tEnter, 0.0) || tEnter > maxT) continue;\n"
	"\n"
	"		uint first = e.range.x, count = e.range.y;\n"
	"		for (uint q = 0u; q < count; q++) {\n"
	"			uint b = (first + q) * 4u;\n"
	"			vec3 v0 = quadVerts[b].xyz, v1 = quadVerts[b + 1u].xyz;\n"
	"			vec3 v2 = quadVerts[b + 2u].xyz, v3 = quadVerts[b + 3u].xyz;\n"
	"			if (hitTriangle(ro, rd, v0, v1, v2, maxT) || hitTriangle(ro, rd, v0, v2, v3, maxT)) return true;\n"
	"		}\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* How much sunlight gets through the clouds along L from p (1 = no cloud) */\n"
	"float cloudShadow(vec3 p, vec3 L) {\n"
	"	if (clouds.w < 0.5 || L.y <= 0.0 || p.y >= clouds.x) return 1.0;\n"
	"	float t  = (clouds.x - p.y) / L.y;\n"
	"	vec2  xz = p.xz + L.xz * t;\n"
	"	/* same mapping as the cloud layer: 2048 blocks per texture repeat, scrolling along U */\n"
	"	vec2  uv = fract(vec2(xz.x / 2048.0 + clouds.y, xz.y / 2048.0));\n"
	"	float a  = textureLod(cloudsTex, uv, 0.0).a;\n"
	"	return 1.0 - a * clouds.z;\n"
	"}\n"
	"\n"
	"/* Direct sunlight contribution for a surface point, tracing a shadow ray towards the sun */\n"
	"vec3 directSun(vec3 p, vec3 n, vec3 L) {\n"
	"	float ndl = dot(n, L);\n"
	"	if (ndl <= 0.0) return vec3(0.0);\n"
	"\n"
	"	Hit sh;\n"
	"	if (traceRay(p, L, 512.0, true, false, sh)) return vec3(0.0);\n"
	"	if (window.z > 0 && hitEntities(p, L, 64.0)) return vec3(0.0);\n"
	"\n"
	"	/* Normalise so that an upward facing face receives the full classic sun colour */\n"
	"	float f = clamp(ndl / max(L.y, 0.2), 0.0, 1.0) * cloudShadow(p, L);\n"
	"	return max(sunlitColour(n) - shadowColour(n), vec3(0.0)) * f;\n"
	"}\n"
	"\n"
	"/* Random number helpers */\n"
	"uint pcgHash(uint v) {\n"
	"	uint state = v * 747796405u + 2891336453u;\n"
	"	uint word  = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;\n"
	"	return (word >> 22u) ^ word;\n"
	"}\n"
	"\n"
	"float rand(inout uint seed) {\n"
	"	seed = pcgHash(seed);\n"
	"	return float(seed) * (1.0 / 4294967296.0);\n"
	"}\n"
	"\n"
	"/* Cosine weighted direction in the hemisphere around n */\n"
	"vec3 cosineSample(vec3 n, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float sr2 = sqrt(r2);\n"
	"	vec3 t = abs(n.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, n));\n"
	"	vec3 v = cross(n, u);\n"
	"	return normalize(u * (cos(phi) * sr2) + v * (sin(phi) * sr2) + n * sqrt(max(0.0, 1.0 - r2)));\n"
	"}\n"
	"\n"
	"/* Random direction inside a cone around dir, tan of half angle = tanRadius */\n"
	"vec3 coneSample(vec3 dir, float tanRadius, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float r   = tanRadius * sqrt(r2);\n"
	"	vec3 t = abs(dir.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, dir));\n"
	"	vec3 v = cross(dir, u);\n"
	"	return normalize(dir + u * (cos(phi) * r) + v * (sin(phi) * r));\n"
	"}\n"
	"\n"
	"/* Light received from emitting blocks (lava, lamps...) by explicitly sampling one of them.\n"
	"   Picks an emitter with probability proportional to 1/distance^2, then traces a ray to it.\n"
	"   Noisy per frame, but the temporal accumulation and blur average it out. */\n"
	"vec3 emitterLight(vec3 p, vec3 n, inout uint seed) {\n"
	"	int count = window.w;\n"
	"	if (count == 0) return vec3(0.0);\n"
	"\n"
	"	float wsum = 0.0, chosenW = 0.0;\n"
	"	int chosen = -1;\n"
	"	for (int i = 0; i < count; i++) {\n"
	"		vec3 d = vec3(emitters[i].xyz) + 0.5 - p;\n"
	"		float d2 = dot(d, d);\n"
	"		if (d2 > 32.0 * 32.0 || dot(d, n) <= 0.0) continue;\n"
	"\n"
	"		float w = 1.0 / max(d2, 1.0);\n"
	"		wsum += w;\n"
	"		if (rand(seed) * wsum < w) { chosen = i; chosenW = w; }\n"
	"	}\n"
	"	if (chosen < 0) return vec3(0.0);\n"
	"\n"
	"	vec3  d    = vec3(emitters[chosen].xyz) + 0.5 - p;\n"
	"	float dist = length(d);\n"
	"	vec3  dir  = d / dist;\n"
	"	Hit eh;\n"
	"	if (!traceRay(p, dir, dist + 1.0, false, true, eh)) return vec3(0.0);\n"
	"	/* must have reached the emitter itself, not something in between */\n"
	"	if (ivec3(floor(eh.pos - eh.normal * 0.5)) != emitters[chosen].xyz) return vec3(0.0);\n"
	"\n"
	"	vec3  Le   = sampleTile(tileFor(eh.block, eh.face), eh.uv, 4.0).rgb * blocks[eh.block].tint.rgb * fogParams.z;\n"
	"	float cosR = max(dot(n, dir), 0.0);\n"
	"	float cosE = max(dot(-dir, eh.normal), 0.0);\n"
	"	float falloff = 1.0 / max(dist * dist, 1.0);\n"
	"	return Le * cosR * cosE * falloff * (wsum / chosenW) / 3.14159265;\n"
	"}\n"
	"\n"
	"/* Temporal accumulation: reprojects each pixel's hit point into the previous\n"
	"   frame and blends the noisy lighting terms with the accumulated history when\n"
	"   the same surface was visible there. */\n"
	"layout(local_size_x = 8, local_size_y = 8) in;\n"
	"\n"
	"/* Inputs are read through samplers: drivers only guarantee 8 image units per shader */\n"
	"layout(binding = 6)  uniform sampler2D gbufCur;\n"
	"layout(binding = 7)  uniform sampler2D normalCur;\n"
	"layout(binding = 8)  uniform sampler2D directCur;\n"
	"layout(binding = 9)  uniform sampler2D indirectCur;\n"
	"layout(binding = 10) uniform sampler2D gbufPrev;\n"
	"layout(binding = 11) uniform sampler2D normalPrev;\n"
	"layout(binding = 12) uniform sampler2D accumDirPrev;\n"
	"layout(binding = 13) uniform sampler2D accumIndPrev;\n"
	"layout(rgba16f, binding = 0) uniform writeonly image2D accumDirOut;  /* rgb = direct, w = history length */\n"
	"layout(rgba16f, binding = 1) uniform writeonly image2D accumIndOut;  /* rgb = indirect, w = history length */\n"
	"\n"
	"#define MAX_HISTORY 48.0\n"
	"\n"
	"void main() {\n"
	"	ivec2 px = ivec2(gl_GlobalInvocationID.xy);\n"
	"	if (px.x >= screen.x || px.y >= screen.y) return;\n"
	"\n"
	"	vec4 g   = texelFetch(gbufCur, px, 0);\n"
	"	vec4 dir = texelFetch(directCur, px, 0);\n"
	"	vec4 ind = texelFetch(indirectCur, px, 0);\n"
	"	if (g.w < 0.0) {\n"
	"		imageStore(accumDirOut, px, vec4(0.0));\n"
	"		imageStore(accumIndOut, px, vec4(0.0));\n"
	"		return;\n"
	"	}\n"
	"\n"
	"	vec4  nrm = texelFetch(normalCur, px, 0);\n"
	"	float history = 0.0;\n"
	"	vec3  prevDir = vec3(0.0), prevInd = vec3(0.0);\n"
	"\n"
	"	/* Where was this world position on screen last frame? */\n"
	"	vec4 prevClip = prevViewProj * vec4(g.xyz, 1.0);\n"
	"	if (prevClip.w > 0.0) {\n"
	"		vec2 prevNdc = prevClip.xy / prevClip.w;\n"
	"		ivec2 pp = ivec2(floor((prevNdc * 0.5 + 0.5) * vec2(screen.xy)));\n"
	"\n"
	"		if (all(greaterThanEqual(pp, ivec2(0))) && all(lessThan(pp, screen.xy))) {\n"
	"			vec4 pg = texelFetch(gbufPrev, pp, 0);\n"
	"			vec4 pn = texelFetch(normalPrev, pp, 0);\n"
	"\n"
	"			bool samePoint  = pg.w > 0.0 && distance(pg.xyz, g.xyz) < 0.02 + 0.004 * g.w;\n"
	"			bool sameNormal = dot(pn.xyz, nrm.xyz) > 0.9;\n"
	"			bool sameBlock  = abs(pn.w - nrm.w) < 0.5;\n"
	"\n"
	"			if (samePoint && sameNormal && sameBlock) {\n"
	"				vec4 ad = texelFetch(accumDirPrev, pp, 0);\n"
	"				vec4 ai = texelFetch(accumIndPrev, pp, 0);\n"
	"				history = ai.w;\n"
	"				prevDir = ad.rgb;\n"
	"				prevInd = ai.rgb;\n"
	"			}\n"
	"		}\n"
	"	}\n"
	"\n"
	"	history = min(history + 1.0, MAX_HISTORY);\n"
	"	float alpha = 1.0 / history;\n"
	"\n"
	"	vec3 outDir = mix(prevDir, dir.rgb, alpha);\n"
	"	vec3 outInd = mix(prevInd, ind.rgb, alpha);\n"
	"	/* Hard shadows are noise free, so don't smear them over time */\n"
	"	if ((screen.w & FLAG_SOFT_SHADOWS) == 0) outDir = dir.rgb;\n"
	"\n"
	"	imageStore(accumDirOut, px, vec4(outDir, history));\n"
	"	imageStore(accumIndOut, px, vec4(outInd, history));\n"
	"}\n"
	"\n";

static const char* const RT_ATROUS_SRC =
	"#version 430\n"
	"/* Shared code for the ClassiCube GPU voxel path tracer (see src/RayTracer.c)\n"
	"   The world is traced directly as a voxel grid using a 3D DDA walk, so no\n"
	"   acceleration structure has to be built or maintained on block changes.\n"
	"   Copyright 2014-2025 ClassiCube | Licensed under BSD-3 */\n"
	"\n"
	"/* Must match struct RTParams in RayTracer.c (std140 layout, vec4/mat4 only) */\n"
	"layout(std140, binding = 0) uniform Params {\n"
	"	mat4  invViewProj;  /* clip space -> world space */\n"
	"	mat4  viewProj;     /* world space -> clip space (current frame) */\n"
	"	mat4  prevViewProj; /* world space -> clip space (previous frame) */\n"
	"	mat4  view;         /* world space -> eye space */\n"
	"	vec4  camPos;       /* xyz = camera position, w = time in seconds */\n"
	"	vec4  sunDir;       /* xyz = direction towards the sun, w = tan(sun angular radius) */\n"
	"	vec4  sunCol, sunXSide, sunZSide, sunYMin;\n"
	"	vec4  shadowCol, shadowXSide, shadowZSide, shadowYMin;\n"
	"	vec4  skyCol;       /* rgb = colour seen by rays that escape the world */\n"
	"	vec4  fogCol;       /* rgb = fog colour, w = exp fog density (0 = linear fog) */\n"
	"	vec4  fogParams;    /* x = linear fog end, y = minimum ambient, z = emissive strength, w = unused */\n"
	"	ivec4 worldSize;    /* xyz = world dimensions */\n"
	"	ivec4 screen;       /* xy = render size, z = frame index, w = flags */\n"
	"	ivec4 atlas;        /* x = atlas1D shift, y = atlas1D mask, z = atlas count, w = tile size in pixels */\n"
	"	vec4  misc;         /* x = atlas1D V per tile, y = max primary distance, z = GI ray distance, w = pixel angular size */\n"
	"	ivec4 window;       /* xy = window size in pixels (render size may be smaller, see rt-scale), z = entity count, w = emitter count */\n"
	"	vec4  clouds;       /* x = clouds height, y = cloud texture scroll offset, z = shadow strength, w = enabled */\n"
	"};\n"
	"\n"
	"#define FLAG_GI          1\n"
	"#define FLAG_REFLECTIONS 2\n"
	"#define FLAG_SOFT_SHADOWS 4\n"
	"\n"
	"/* Must match struct RTBlockInfo in RayTracer.c */\n"
	"struct BlockInfo {\n"
	"	vec4  minBB;  /* xyz = min bounds, w = draw type */\n"
	"	vec4  maxBB;  /* xyz = max bounds, w = flags */\n"
	"	uvec4 texA;   /* tile ids for faces XMIN, XMAX, ZMIN, ZMAX */\n"
	"	uvec4 texB;   /* tile ids for faces YMIN, YMAX, then unused */\n"
	"	vec4  tint;   /* rgb = colour multiplier, w = 1 if block is full bright */\n"
	"};\n"
	"\n"
	"layout(std430, binding = 1) readonly buffer BlockTable { BlockInfo blocks[]; };\n"
	"\n"
	"layout(binding = 1) uniform usampler3D worldTex;\n"
	"layout(binding = 2) uniform sampler2D atlas0;\n"
	"layout(binding = 3) uniform sampler2D atlas1;\n"
	"layout(binding = 4) uniform sampler2D atlas2;\n"
	"layout(binding = 5) uniform sampler2D atlas3;\n"
	"/* 1 byte per 8x8x8 region of the world: 0 if the region is entirely air, so rays can skip it */\n"
	"layout(binding = 14) uniform usampler3D coarseTex;\n"
	"#define COARSE_SHIFT 3\n"
	"#define COARSE_SIZE  8.0\n"
	"/* The game's cloud texture, for cloud shadows */\n"
	"layout(binding = 15) uniform sampler2D cloudsTex;\n"
	"\n"
	"/* Entity models drawn this frame, recorded as world space quads (must match RTEntity in RayTracer.c) */\n"
	"struct EntityInfo {\n"
	"	vec4  bbMin;\n"
	"	vec4  bbMax;\n"
	"	uvec4 range;  /* x = first quad, y = quad count */\n"
	"};\n"
	"layout(std430, binding = 2) readonly buffer EntityTable { EntityInfo entities[]; };\n"
	"layout(std430, binding = 3) readonly buffer EntityQuads { vec4 quadVerts[]; };\n"
	"/* Light emitting blocks near the camera: xyz = block position, w = block id */\n"
	"layout(std430, binding = 4) readonly buffer EmitterTable { ivec4 emitters[]; };\n"
	"\n"
	"#define DRAW_OPAQUE            0\n"
	"#define DRAW_TRANSPARENT       1\n"
	"#define DRAW_TRANSPARENT_THICK 2\n"
	"#define DRAW_TRANSLUCENT       3\n"
	"#define DRAW_GAS               4\n"
	"#define DRAW_SPRITE            5\n"
	"\n"
	"#define BLOCKFLAG_BLOCKS_LIGHT 1\n"
	"\n"
	"#define FACE_XMIN 0\n"
	"#define FACE_XMAX 1\n"
	"#define FACE_ZMIN 2\n"
	"#define FACE_ZMAX 3\n"
	"#define FACE_YMIN 4\n"
	"#define FACE_YMAX 5\n"
	"\n"
	"#define MAX_DDA_STEPS 1024\n"
	"\n"
	"struct Hit {\n"
	"	vec3  pos;     /* world space hit position */\n"
	"	vec3  normal;  /* geometric normal facing the ray */\n"
	"	vec2  uv;      /* texture coordinates within the tile */\n"
	"	float t;       /* distance along the ray */\n"
	"	uint  block;   /* block id that was hit */\n"
	"	uint  face;    /* FACE_ constant of hit face */\n"
	"	uint  draw;    /* draw type of hit block */\n"
	"};\n"
	"\n"
	"int  drawType(uint block)  { return int(blocks[block].minBB.w); }\n"
	"bool blocksLight(uint block) { return (int(blocks[block].maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) != 0; }\n"
	"bool fullBright(uint block) { return blocks[block].tint.w > 0.5; }\n"
	"\n"
	"uint tileFor(uint block, uint face) {\n"
	"	/* NOTE: NVIDIA's compiler rejects a constant out of range index even in a branch that */\n"
	"	/*  can't be taken, so the index must stay in range for every possible face value */\n"
	"	uvec4 tiles = (face < 4u) ? blocks[block].texA : blocks[block].texB;\n"
	"	return tiles[face & 3u];\n"
	"}\n"
	"\n"
	"uint coarseAt(ivec3 cc) {\n"
	"	return texelFetch(coarseTex, ivec3(cc.x, cc.z, cc.y), 0).r;\n"
	"}\n"
	"\n"
	"uint blockAt(ivec3 p) {\n"
	"	if (any(lessThan(p, ivec3(0))) || any(greaterThanEqual(p, worldSize.xyz))) return 0u;\n"
	"	/* world texture is stored as (x, z, y) so that height is the depth axis */\n"
	"	return texelFetch(worldTex, ivec3(p.x, p.z, p.y), 0).r;\n"
	"}\n"
	"\n"
	"vec4 sampleTile(uint texLoc, vec2 uv, float lod) {\n"
	"	uint idx = texLoc >> uint(atlas.x);\n"
	"	uint row = texLoc &  uint(atlas.y);\n"
	"	/* keep slightly inside the tile, so mipmaps/filtering don't bleed neighbouring tiles */\n"
	"	float pad = 0.5 / float(atlas.w);\n"
	"	uv = clamp(uv, vec2(pad), vec2(1.0 - pad));\n"
	"	vec2 st = vec2(uv.x, (float(row) + uv.y) * misc.x);\n"
	"\n"
	"	if (idx == 0u) return textureLod(atlas0, st, lod);\n"
	"	if (idx == 1u) return textureLod(atlas1, st, lod);\n"
	"	if (idx == 2u) return textureLod(atlas2, st, lod);\n"
	"	return textureLod(atlas3, st, lod);\n"
	"}\n"
	"\n"
	"/* Texture coordinates for a point on the given face, matching Drawer.c orientation */\n"
	"vec2 faceUV(uint face, vec3 local) {\n"
	"	if (face == FACE_XMIN) return vec2(local.z,       1.0 - local.y);\n"
	"	if (face == FACE_XMAX) return vec2(1.0 - local.z, 1.0 - local.y);\n"
	"	if (face == FACE_ZMIN) return vec2(1.0 - local.x, 1.0 - local.y);\n"
	"	if (face == FACE_ZMAX) return vec2(local.x,       1.0 - local.y);\n"
	"	return vec2(local.x, local.z); /* YMIN / YMAX */\n"
	"}\n"
	"\n"
	"/* Whether a texel of the given tile should be treated as solid for alpha tested blocks */\n"
	"bool texelSolid(uint block, uint face, vec2 uv) {\n"
	"	return sampleTile(tileFor(block, face), uv, 0.0).a > 0.5;\n"
	"}\n"
	"\n"
	"/* Intersects the ray with the geometry of one block inside cell c.\n"
	"   tMin/tMax bound the ray segment that lies inside the cell */\n"
	"bool hitCell(ivec3 c, uint block, vec3 ro, vec3 rd, vec3 invRd, float tMin, float tMax, bool shadowRay, bool skipTranslucent, inout Hit h) {\n"
	"	BlockInfo bi = blocks[block];\n"
	"	int  draw = int(bi.minBB.w);\n"
	"	vec3 base = vec3(c);\n"
	"\n"
	"	if (draw == DRAW_GAS) return false;\n"
	"	if (shadowRay && (int(bi.maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) == 0) return false;\n"
	"	if (draw == DRAW_TRANSLUCENT && skipTranslucent) return false;\n"
	"\n"
	"	if (draw == DRAW_SPRITE) {\n"
	"		/* Two crossed quads along the diagonals of the cell */\n"
	"		float bestT = 1e30;\n"
	"		vec2  bestUV = vec2(0.0);\n"
	"		vec3  bestN  = vec3(0.0);\n"
	"		vec3  o = ro - base;\n"
	"\n"
	"		for (int i = 0; i < 2; i++) {\n"
	"			/* plane i = 0: x == z    plane i = 1: x == 1 - z */\n"
	"			vec3 n = (i == 0) ? vec3(1.0, 0.0, -1.0) : vec3(1.0, 0.0, 1.0);\n"
	"			float d = (i == 0) ? 0.0 : 1.0;\n"
	"			float denom = dot(rd, n);\n"
	"			if (abs(denom) < 1e-6) continue;\n"
	"\n"
	"			float t = (d - dot(o, n)) / denom;\n"
	"			if (t < tMin - 1e-4 || t > tMax + 1e-4 || t >= bestT) continue;\n"
	"\n"
	"			vec3 p = o + rd * t;\n"
	"			if (p.y < 0.0 || p.y > 1.0 || p.x < 0.0 || p.x > 1.0 || p.z < 0.0 || p.z > 1.0) continue;\n"
	"\n"
	"			vec2 uv = vec2(p.x, 1.0 - p.y);\n"
	"			if (!texelSolid(block, FACE_XMIN, uv)) continue;\n"
	"\n"
	"			bestT  = t;\n"
	"			bestUV = uv;\n"
	"			bestN  = normalize(n) * ((denom > 0.0) ? -1.0 : 1.0);\n"
	"		}\n"
	"		if (bestT >= 1e30) return false;\n"
	"\n"
	"		h.t = bestT; h.pos = ro + rd * bestT; h.normal = bestN; h.uv = bestUV;\n"
	"		h.block = block; h.face = FACE_XMIN; h.draw = uint(draw);\n"
	"		return true;\n"
	"	}\n"
	"\n"
	"	vec3 bmin = base + bi.minBB.xyz;\n"
	"	vec3 bmax = base + bi.maxBB.xyz;\n"
	"	vec3 t1 = (bmin - ro) * invRd;\n"
	"	vec3 t2 = (bmax - ro) * invRd;\n"
	"	vec3 tn = min(t1, t2);\n"
	"	vec3 tf = max(t1, t2);\n"
	"	float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"	float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"\n"
	"	/* small tolerance, since the DDA's accumulated cell boundaries drift slightly from the exact slab distances */\n"
	"	if (tExit < tEnter || tExit < tMin - 1e-4 || tEnter > tMax + 1e-4) return false;\n"
	"	/* ray starts inside this block - look through it (like backface culling does) */\n"
	"	if (tEnter < 0.0) return false;\n"
	"\n"
	"	vec3 normal; uint face;\n"
	"	if (tEnter == tn.x) {\n"
	"		normal = vec3(rd.x > 0.0 ? -1.0 : 1.0, 0.0, 0.0);\n"
	"		face   = rd.x > 0.0 ? FACE_XMIN : FACE_XMAX;\n"
	"	} else if (tEnter == tn.y) {\n"
	"		normal = vec3(0.0, rd.y > 0.0 ? -1.0 : 1.0, 0.0);\n"
	"		face   = rd.y > 0.0 ? FACE_YMIN : FACE_YMAX;\n"
	"	} else {\n"
	"		normal = vec3(0.0, 0.0, rd.z > 0.0 ? -1.0 : 1.0);\n"
	"		face   = rd.z > 0.0 ? FACE_ZMIN : FACE_ZMAX;\n"
	"	}\n"
	"\n"
	"	/* Faces shared with an identical neighbouring block aren't drawn (e.g. between two water */\n"
	"	/*  blocks, which are slightly lower than a full cell so rays can slip between them) */\n"
	"	if (draw != DRAW_TRANSPARENT_THICK && blockAt(c + ivec3(normal)) == block) return false;\n"
	"\n"
	"	vec3 local = clamp(ro + rd * tEnter - base, 0.0, 1.0);\n"
	"	vec2 uv    = faceUV(face, local);\n"
	"\n"
	"	if (draw == DRAW_TRANSPARENT || draw == DRAW_TRANSPARENT_THICK) {\n"
	"		if (!texelSolid(block, face, uv)) return false;\n"
	"	}\n"
	"\n"
	"	h.t = tEnter; h.pos = ro + rd * tEnter; h.normal = normal; h.uv = uv;\n"
	"	h.block = block; h.face = face; h.draw = uint(draw);\n"
	"	return true;\n"
	"}\n"
	"\n"
	"/* Walks the voxel grid along the ray. Returns true if any block geometry was hit within maxT */\n"
	"bool traceRay(vec3 ro, vec3 rd, float maxT, bool shadowRay, bool skipTranslucent, out Hit h) {\n"
	"	vec3  wsize = vec3(worldSize.xyz);\n"
	"	float tOffset = 0.0;\n"
	"	h.t = -1.0; h.block = 0u;\n"
	"\n"
	"	/* Clip the ray to the world bounds first */\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	if (any(lessThan(ro, vec3(0.0))) || any(greaterThanEqual(ro, wsize))) {\n"
	"		vec3 t1 = (vec3(0.0) - ro) * invRd;\n"
	"		vec3 t2 = (wsize      - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2);\n"
	"		vec3 tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < tEnter || tExit < 0.0 || tEnter > maxT) return false;\n"
	"\n"
	"		tOffset = max(tEnter, 0.0) + 1e-4;\n"
	"		ro     += rd * tOffset;\n"
	"		maxT   -= tOffset;\n"
	"	}\n"
	"\n"
	"	ivec3 c   = ivec3(floor(ro));\n"
	"	c = clamp(c, ivec3(0), worldSize.xyz - 1);\n"
	"	ivec3 stp = ivec3(sign(rd));\n"
	"	vec3  side = vec3(greaterThan(rd, vec3(0.0)));\n"
	"	float t = 0.0;\n"
	"	ivec3 lastCoarse = ivec3(-1);\n"
	"	bool  coarseEmpty = false;\n"
	"\n"
	"	for (int i = 0; i < MAX_DDA_STEPS; i++) {\n"
	"		ivec3 cc = c >> COARSE_SHIFT;\n"
	"		if (cc != lastCoarse) {\n"
	"			lastCoarse  = cc;\n"
	"			coarseEmpty = coarseAt(cc) == 0u;\n"
	"		}\n"
	"\n"
	"		if (coarseEmpty) {\n"
	"			/* Whole 8x8x8 region is air - jump straight to where the ray leaves it */\n"
	"			vec3 cmin = vec3(cc << COARSE_SHIFT);\n"
	"			vec3 tf = max((cmin - ro) * invRd, (cmin + COARSE_SIZE - ro) * invRd);\n"
	"			if (rd.x == 0.0) tf.x = 1e30;\n"
	"			if (rd.y == 0.0) tf.y = 1e30;\n"
	"			if (rd.z == 0.0) tf.z = 1e30;\n"
	"			t = min(min(tf.x, tf.y), tf.z);\n"
	"			if (t > maxT) return false;\n"
	"\n"
	"			ivec3 lo = cc << COARSE_SHIFT;\n"
	"			c = clamp(ivec3(floor(ro + rd * t)), lo, lo + int(COARSE_SIZE) - 1);\n"
	"			/* step the axis that was crossed into the neighbouring region exactly */\n"
	"			if (t == tf.x)      c.x = (stp.x > 0) ? lo.x + int(COARSE_SIZE) : lo.x - 1;\n"
	"			else if (t == tf.y) c.y = (stp.y > 0) ? lo.y + int(COARSE_SIZE) : lo.y - 1;\n"
	"			else                c.z = (stp.z > 0) ? lo.z + int(COARSE_SIZE) : lo.z - 1;\n"
	"\n"
	"			if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"			continue;\n"
	"		}\n"
	"\n"
	"		/* Distance to each of the three cell boundaries in front of the ray. Recomputed from the */\n"
	"		/*  cell coordinates every step, so no floating point drift accumulates between the cell */\n"
	"		/*  walk and the exact slab tests in hitCell (drift caused cracks between blocks) */\n"
	"		vec3 tNext = (vec3(c) + side - ro) * invRd;\n"
	"		if (rd.x == 0.0) tNext.x = 1e30;\n"
	"		if (rd.y == 0.0) tNext.y = 1e30;\n"
	"		if (rd.z == 0.0) tNext.z = 1e30;\n"
	"		float tExit = min(min(tNext.x, tNext.y), tNext.z);\n"
	"		uint  b = blockAt(c);\n"
	"\n"
	"		if (b != 0u) {\n"
	"			if (hitCell(c, b, ro, rd, invRd, t, min(tExit, maxT), shadowRay, skipTranslucent, h)) {\n"
	"				h.t += tOffset;\n"
	"				return true;\n"
	"			}\n"
	"		}\n"
	"\n"
	"		if (tNext.x < tNext.y && tNext.x < tNext.z) {\n"
	"			c.x += stp.x;\n"
	"		} else if (tNext.y < tNext.z) {\n"
	"			c.y += stp.y;\n"
	"		} else {\n"
	"			c.z += stp.z;\n"
	"		}\n"
	"		t = tExit;\n"
	"\n"
	"		if (t > maxT) return false;\n"
	"		if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* Colour of a face when in direct sunlight, following the classic per-face shading */\n"
	"vec3 sunlitColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return sunCol.rgb;\n"
	"	if (n.y < -0.5) return sunYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return sunXSide.rgb;\n"
	"	return sunZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Colour of a face when only lit by the sky */\n"
	"vec3 shadowColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return shadowCol.rgb;\n"
	"	if (n.y < -0.5) return shadowYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return shadowXSide.rgb;\n"
	"	return shadowZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Moller-Trumbore ray/triangle test, both sides */\n"
	"bool hitTriangle(vec3 ro, vec3 rd, vec3 a, vec3 b, vec3 c, float maxT) {\n"
	"	vec3 e1 = b - a, e2 = c - a;\n"
	"	vec3 pv = cross(rd, e2);\n"
	"	float det = dot(e1, pv);\n"
	"	if (abs(det) < 1e-7) return false;\n"
	"	float inv = 1.0 / det;\n"
	"	vec3 tv = ro - a;\n"
	"	float u = dot(tv, pv) * inv;\n"
	"	if (u < 0.0 || u > 1.0) return false;\n"
	"	vec3 qv = cross(tv, e1);\n"
	"	float v = dot(rd, qv) * inv;\n"
	"	if (v < 0.0 || u + v > 1.0) return false;\n"
	"	float t = dot(e2, qv) * inv;\n"
	"	return t > 1e-3 && t < maxT;\n"
	"}\n"
	"\n"
	"/* Whether the ray hits any entity (player) model recorded this frame */\n"
	"bool hitEntities(vec3 ro, vec3 rd, float maxT) {\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	for (int i = 0; i < window.z; i++) {\n"
	"		EntityInfo e = entities[i];\n"
	"		vec3 t1 = (e.bbMin.xyz - ro) * invRd;\n"
	"		vec3 t2 = (e.bbMax.xyz - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2), tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < max(tEnter, 0.0) || tEnter > maxT) continue;\n"
	"\n"
	"		uint first = e.range.x, count = e.range.y;\n"
	"		for (uint q = 0u; q < count; q++) {\n"
	"			uint b = (first + q) * 4u;\n"
	"			vec3 v0 = quadVerts[b].xyz, v1 = quadVerts[b + 1u].xyz;\n"
	"			vec3 v2 = quadVerts[b + 2u].xyz, v3 = quadVerts[b + 3u].xyz;\n"
	"			if (hitTriangle(ro, rd, v0, v1, v2, maxT) || hitTriangle(ro, rd, v0, v2, v3, maxT)) return true;\n"
	"		}\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* How much sunlight gets through the clouds along L from p (1 = no cloud) */\n"
	"float cloudShadow(vec3 p, vec3 L) {\n"
	"	if (clouds.w < 0.5 || L.y <= 0.0 || p.y >= clouds.x) return 1.0;\n"
	"	float t  = (clouds.x - p.y) / L.y;\n"
	"	vec2  xz = p.xz + L.xz * t;\n"
	"	/* same mapping as the cloud layer: 2048 blocks per texture repeat, scrolling along U */\n"
	"	vec2  uv = fract(vec2(xz.x / 2048.0 + clouds.y, xz.y / 2048.0));\n"
	"	float a  = textureLod(cloudsTex, uv, 0.0).a;\n"
	"	return 1.0 - a * clouds.z;\n"
	"}\n"
	"\n"
	"/* Direct sunlight contribution for a surface point, tracing a shadow ray towards the sun */\n"
	"vec3 directSun(vec3 p, vec3 n, vec3 L) {\n"
	"	float ndl = dot(n, L);\n"
	"	if (ndl <= 0.0) return vec3(0.0);\n"
	"\n"
	"	Hit sh;\n"
	"	if (traceRay(p, L, 512.0, true, false, sh)) return vec3(0.0);\n"
	"	if (window.z > 0 && hitEntities(p, L, 64.0)) return vec3(0.0);\n"
	"\n"
	"	/* Normalise so that an upward facing face receives the full classic sun colour */\n"
	"	float f = clamp(ndl / max(L.y, 0.2), 0.0, 1.0) * cloudShadow(p, L);\n"
	"	return max(sunlitColour(n) - shadowColour(n), vec3(0.0)) * f;\n"
	"}\n"
	"\n"
	"/* Random number helpers */\n"
	"uint pcgHash(uint v) {\n"
	"	uint state = v * 747796405u + 2891336453u;\n"
	"	uint word  = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;\n"
	"	return (word >> 22u) ^ word;\n"
	"}\n"
	"\n"
	"float rand(inout uint seed) {\n"
	"	seed = pcgHash(seed);\n"
	"	return float(seed) * (1.0 / 4294967296.0);\n"
	"}\n"
	"\n"
	"/* Cosine weighted direction in the hemisphere around n */\n"
	"vec3 cosineSample(vec3 n, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float sr2 = sqrt(r2);\n"
	"	vec3 t = abs(n.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, n));\n"
	"	vec3 v = cross(n, u);\n"
	"	return normalize(u * (cos(phi) * sr2) + v * (sin(phi) * sr2) + n * sqrt(max(0.0, 1.0 - r2)));\n"
	"}\n"
	"\n"
	"/* Random direction inside a cone around dir, tan of half angle = tanRadius */\n"
	"vec3 coneSample(vec3 dir, float tanRadius, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float r   = tanRadius * sqrt(r2);\n"
	"	vec3 t = abs(dir.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, dir));\n"
	"	vec3 v = cross(dir, u);\n"
	"	return normalize(dir + u * (cos(phi) * r) + v * (sin(phi) * r));\n"
	"}\n"
	"\n"
	"/* Light received from emitting blocks (lava, lamps...) by explicitly sampling one of them.\n"
	"   Picks an emitter with probability proportional to 1/distance^2, then traces a ray to it.\n"
	"   Noisy per frame, but the temporal accumulation and blur average it out. */\n"
	"vec3 emitterLight(vec3 p, vec3 n, inout uint seed) {\n"
	"	int count = window.w;\n"
	"	if (count == 0) return vec3(0.0);\n"
	"\n"
	"	float wsum = 0.0, chosenW = 0.0;\n"
	"	int chosen = -1;\n"
	"	for (int i = 0; i < count; i++) {\n"
	"		vec3 d = vec3(emitters[i].xyz) + 0.5 - p;\n"
	"		float d2 = dot(d, d);\n"
	"		if (d2 > 32.0 * 32.0 || dot(d, n) <= 0.0) continue;\n"
	"\n"
	"		float w = 1.0 / max(d2, 1.0);\n"
	"		wsum += w;\n"
	"		if (rand(seed) * wsum < w) { chosen = i; chosenW = w; }\n"
	"	}\n"
	"	if (chosen < 0) return vec3(0.0);\n"
	"\n"
	"	vec3  d    = vec3(emitters[chosen].xyz) + 0.5 - p;\n"
	"	float dist = length(d);\n"
	"	vec3  dir  = d / dist;\n"
	"	Hit eh;\n"
	"	if (!traceRay(p, dir, dist + 1.0, false, true, eh)) return vec3(0.0);\n"
	"	/* must have reached the emitter itself, not something in between */\n"
	"	if (ivec3(floor(eh.pos - eh.normal * 0.5)) != emitters[chosen].xyz) return vec3(0.0);\n"
	"\n"
	"	vec3  Le   = sampleTile(tileFor(eh.block, eh.face), eh.uv, 4.0).rgb * blocks[eh.block].tint.rgb * fogParams.z;\n"
	"	float cosR = max(dot(n, dir), 0.0);\n"
	"	float cosE = max(dot(-dir, eh.normal), 0.0);\n"
	"	float falloff = 1.0 / max(dist * dist, 1.0);\n"
	"	return Le * cosR * cosE * falloff * (wsum / chosenW) / 3.14159265;\n"
	"}\n"
	"\n"
	"/* Edge-aware a-trous wavelet blur for the indirect lighting term.\n"
	"   Run several times with increasing step sizes (1, 2, 4). Pixels with a long\n"
	"   accumulated history are already converged and get blurred less. */\n"
	"layout(local_size_x = 8, local_size_y = 8) in;\n"
	"\n"
	"layout(binding = 6) uniform sampler2D gbufCur;\n"
	"layout(binding = 7) uniform sampler2D normalCur;\n"
	"layout(binding = 8) uniform sampler2D srcImg;\n"
	"layout(rgba16f, binding = 0) uniform writeonly image2D dstImg;\n"
	"\n"
	"uniform int stepSize;\n"
	"\n"
	"void main() {\n"
	"	ivec2 px = ivec2(gl_GlobalInvocationID.xy);\n"
	"	if (px.x >= screen.x || px.y >= screen.y) return;\n"
	"\n"
	"	vec4 g = texelFetch(gbufCur, px, 0);\n"
	"	vec4 c = texelFetch(srcImg, px, 0);\n"
	"	if (g.w < 0.0) { imageStore(dstImg, px, c); return; }\n"
	"\n"
	"	vec4  n = texelFetch(normalCur, px, 0);\n"
	"	/* Less blur once enough samples have accumulated */\n"
	"	float historyScale = clamp(1.0 - c.w / 48.0, 0.15, 1.0);\n"
	"	float kernel[5] = float[5](1.0 / 16.0, 1.0 / 4.0, 3.0 / 8.0, 1.0 / 4.0, 1.0 / 16.0);\n"
	"\n"
	"	vec3  sum = vec3(0.0);\n"
	"	float wsum = 0.0;\n"
	"\n"
	"	for (int j = -2; j <= 2; j++) {\n"
	"		for (int i = -2; i <= 2; i++) {\n"
	"			ivec2 q = px + ivec2(i, j) * stepSize;\n"
	"			if (q.x < 0 || q.y < 0 || q.x >= screen.x || q.y >= screen.y) continue;\n"
	"\n"
	"			vec4 gq = texelFetch(gbufCur, q, 0);\n"
	"			if (gq.w < 0.0) continue;\n"
	"			vec4 nq = texelFetch(normalCur, q, 0);\n"
	"			if (dot(nq.xyz, n.xyz) < 0.9) continue;\n"
	"\n"
	"			/* distance of the neighbour from this pixel's surface plane */\n"
	"			float planeDist = abs(dot(gq.xyz - g.xyz, n.xyz));\n"
	"			float w = kernel[i + 2] * kernel[j + 2] * exp(-planeDist * planeDist * 400.0);\n"
	"			if (i != 0 || j != 0) w *= historyScale;\n"
	"			if (abs(nq.w - n.w) > 0.5) w *= 0.25;\n"
	"\n"
	"			sum  += texelFetch(srcImg, q, 0).rgb * w;\n"
	"			wsum += w;\n"
	"		}\n"
	"	}\n"
	"\n"
	"	vec3 result = wsum > 0.0 ? sum / wsum : c.rgb;\n"
	"	imageStore(dstImg, px, vec4(result, c.w));\n"
	"}\n"
	"\n";

static const char* const RT_COMPOSITE_VS =
	"#version 430\n"
	"/* Full screen triangle, no vertex buffer needed */\n"
	"void main() {\n"
	"	vec2 p = vec2((gl_VertexID == 1) ? 3.0 : -1.0, (gl_VertexID == 2) ? 3.0 : -1.0);\n"
	"	gl_Position = vec4(p, 0.0, 1.0);\n"
	"}\n"
	"\n";

static const char* const RT_COMPOSITE_FS =
	"#version 430\n"
	"/* Shared code for the ClassiCube GPU voxel path tracer (see src/RayTracer.c)\n"
	"   The world is traced directly as a voxel grid using a 3D DDA walk, so no\n"
	"   acceleration structure has to be built or maintained on block changes.\n"
	"   Copyright 2014-2025 ClassiCube | Licensed under BSD-3 */\n"
	"\n"
	"/* Must match struct RTParams in RayTracer.c (std140 layout, vec4/mat4 only) */\n"
	"layout(std140, binding = 0) uniform Params {\n"
	"	mat4  invViewProj;  /* clip space -> world space */\n"
	"	mat4  viewProj;     /* world space -> clip space (current frame) */\n"
	"	mat4  prevViewProj; /* world space -> clip space (previous frame) */\n"
	"	mat4  view;         /* world space -> eye space */\n"
	"	vec4  camPos;       /* xyz = camera position, w = time in seconds */\n"
	"	vec4  sunDir;       /* xyz = direction towards the sun, w = tan(sun angular radius) */\n"
	"	vec4  sunCol, sunXSide, sunZSide, sunYMin;\n"
	"	vec4  shadowCol, shadowXSide, shadowZSide, shadowYMin;\n"
	"	vec4  skyCol;       /* rgb = colour seen by rays that escape the world */\n"
	"	vec4  fogCol;       /* rgb = fog colour, w = exp fog density (0 = linear fog) */\n"
	"	vec4  fogParams;    /* x = linear fog end, y = minimum ambient, z = emissive strength, w = unused */\n"
	"	ivec4 worldSize;    /* xyz = world dimensions */\n"
	"	ivec4 screen;       /* xy = render size, z = frame index, w = flags */\n"
	"	ivec4 atlas;        /* x = atlas1D shift, y = atlas1D mask, z = atlas count, w = tile size in pixels */\n"
	"	vec4  misc;         /* x = atlas1D V per tile, y = max primary distance, z = GI ray distance, w = pixel angular size */\n"
	"	ivec4 window;       /* xy = window size in pixels (render size may be smaller, see rt-scale), z = entity count, w = emitter count */\n"
	"	vec4  clouds;       /* x = clouds height, y = cloud texture scroll offset, z = shadow strength, w = enabled */\n"
	"};\n"
	"\n"
	"#define FLAG_GI          1\n"
	"#define FLAG_REFLECTIONS 2\n"
	"#define FLAG_SOFT_SHADOWS 4\n"
	"\n"
	"/* Must match struct RTBlockInfo in RayTracer.c */\n"
	"struct BlockInfo {\n"
	"	vec4  minBB;  /* xyz = min bounds, w = draw type */\n"
	"	vec4  maxBB;  /* xyz = max bounds, w = flags */\n"
	"	uvec4 texA;   /* tile ids for faces XMIN, XMAX, ZMIN, ZMAX */\n"
	"	uvec4 texB;   /* tile ids for faces YMIN, YMAX, then unused */\n"
	"	vec4  tint;   /* rgb = colour multiplier, w = 1 if block is full bright */\n"
	"};\n"
	"\n"
	"layout(std430, binding = 1) readonly buffer BlockTable { BlockInfo blocks[]; };\n"
	"\n"
	"layout(binding = 1) uniform usampler3D worldTex;\n"
	"layout(binding = 2) uniform sampler2D atlas0;\n"
	"layout(binding = 3) uniform sampler2D atlas1;\n"
	"layout(binding = 4) uniform sampler2D atlas2;\n"
	"layout(binding = 5) uniform sampler2D atlas3;\n"
	"/* 1 byte per 8x8x8 region of the world: 0 if the region is entirely air, so rays can skip it */\n"
	"layout(binding = 14) uniform usampler3D coarseTex;\n"
	"#define COARSE_SHIFT 3\n"
	"#define COARSE_SIZE  8.0\n"
	"/* The game's cloud texture, for cloud shadows */\n"
	"layout(binding = 15) uniform sampler2D cloudsTex;\n"
	"\n"
	"/* Entity models drawn this frame, recorded as world space quads (must match RTEntity in RayTracer.c) */\n"
	"struct EntityInfo {\n"
	"	vec4  bbMin;\n"
	"	vec4  bbMax;\n"
	"	uvec4 range;  /* x = first quad, y = quad count */\n"
	"};\n"
	"layout(std430, binding = 2) readonly buffer EntityTable { EntityInfo entities[]; };\n"
	"layout(std430, binding = 3) readonly buffer EntityQuads { vec4 quadVerts[]; };\n"
	"/* Light emitting blocks near the camera: xyz = block position, w = block id */\n"
	"layout(std430, binding = 4) readonly buffer EmitterTable { ivec4 emitters[]; };\n"
	"\n"
	"#define DRAW_OPAQUE            0\n"
	"#define DRAW_TRANSPARENT       1\n"
	"#define DRAW_TRANSPARENT_THICK 2\n"
	"#define DRAW_TRANSLUCENT       3\n"
	"#define DRAW_GAS               4\n"
	"#define DRAW_SPRITE            5\n"
	"\n"
	"#define BLOCKFLAG_BLOCKS_LIGHT 1\n"
	"\n"
	"#define FACE_XMIN 0\n"
	"#define FACE_XMAX 1\n"
	"#define FACE_ZMIN 2\n"
	"#define FACE_ZMAX 3\n"
	"#define FACE_YMIN 4\n"
	"#define FACE_YMAX 5\n"
	"\n"
	"#define MAX_DDA_STEPS 1024\n"
	"\n"
	"struct Hit {\n"
	"	vec3  pos;     /* world space hit position */\n"
	"	vec3  normal;  /* geometric normal facing the ray */\n"
	"	vec2  uv;      /* texture coordinates within the tile */\n"
	"	float t;       /* distance along the ray */\n"
	"	uint  block;   /* block id that was hit */\n"
	"	uint  face;    /* FACE_ constant of hit face */\n"
	"	uint  draw;    /* draw type of hit block */\n"
	"};\n"
	"\n"
	"int  drawType(uint block)  { return int(blocks[block].minBB.w); }\n"
	"bool blocksLight(uint block) { return (int(blocks[block].maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) != 0; }\n"
	"bool fullBright(uint block) { return blocks[block].tint.w > 0.5; }\n"
	"\n"
	"uint tileFor(uint block, uint face) {\n"
	"	/* NOTE: NVIDIA's compiler rejects a constant out of range index even in a branch that */\n"
	"	/*  can't be taken, so the index must stay in range for every possible face value */\n"
	"	uvec4 tiles = (face < 4u) ? blocks[block].texA : blocks[block].texB;\n"
	"	return tiles[face & 3u];\n"
	"}\n"
	"\n"
	"uint coarseAt(ivec3 cc) {\n"
	"	return texelFetch(coarseTex, ivec3(cc.x, cc.z, cc.y), 0).r;\n"
	"}\n"
	"\n"
	"uint blockAt(ivec3 p) {\n"
	"	if (any(lessThan(p, ivec3(0))) || any(greaterThanEqual(p, worldSize.xyz))) return 0u;\n"
	"	/* world texture is stored as (x, z, y) so that height is the depth axis */\n"
	"	return texelFetch(worldTex, ivec3(p.x, p.z, p.y), 0).r;\n"
	"}\n"
	"\n"
	"vec4 sampleTile(uint texLoc, vec2 uv, float lod) {\n"
	"	uint idx = texLoc >> uint(atlas.x);\n"
	"	uint row = texLoc &  uint(atlas.y);\n"
	"	/* keep slightly inside the tile, so mipmaps/filtering don't bleed neighbouring tiles */\n"
	"	float pad = 0.5 / float(atlas.w);\n"
	"	uv = clamp(uv, vec2(pad), vec2(1.0 - pad));\n"
	"	vec2 st = vec2(uv.x, (float(row) + uv.y) * misc.x);\n"
	"\n"
	"	if (idx == 0u) return textureLod(atlas0, st, lod);\n"
	"	if (idx == 1u) return textureLod(atlas1, st, lod);\n"
	"	if (idx == 2u) return textureLod(atlas2, st, lod);\n"
	"	return textureLod(atlas3, st, lod);\n"
	"}\n"
	"\n"
	"/* Texture coordinates for a point on the given face, matching Drawer.c orientation */\n"
	"vec2 faceUV(uint face, vec3 local) {\n"
	"	if (face == FACE_XMIN) return vec2(local.z,       1.0 - local.y);\n"
	"	if (face == FACE_XMAX) return vec2(1.0 - local.z, 1.0 - local.y);\n"
	"	if (face == FACE_ZMIN) return vec2(1.0 - local.x, 1.0 - local.y);\n"
	"	if (face == FACE_ZMAX) return vec2(local.x,       1.0 - local.y);\n"
	"	return vec2(local.x, local.z); /* YMIN / YMAX */\n"
	"}\n"
	"\n"
	"/* Whether a texel of the given tile should be treated as solid for alpha tested blocks */\n"
	"bool texelSolid(uint block, uint face, vec2 uv) {\n"
	"	return sampleTile(tileFor(block, face), uv, 0.0).a > 0.5;\n"
	"}\n"
	"\n"
	"/* Intersects the ray with the geometry of one block inside cell c.\n"
	"   tMin/tMax bound the ray segment that lies inside the cell */\n"
	"bool hitCell(ivec3 c, uint block, vec3 ro, vec3 rd, vec3 invRd, float tMin, float tMax, bool shadowRay, bool skipTranslucent, inout Hit h) {\n"
	"	BlockInfo bi = blocks[block];\n"
	"	int  draw = int(bi.minBB.w);\n"
	"	vec3 base = vec3(c);\n"
	"\n"
	"	if (draw == DRAW_GAS) return false;\n"
	"	if (shadowRay && (int(bi.maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) == 0) return false;\n"
	"	if (draw == DRAW_TRANSLUCENT && skipTranslucent) return false;\n"
	"\n"
	"	if (draw == DRAW_SPRITE) {\n"
	"		/* Two crossed quads along the diagonals of the cell */\n"
	"		float bestT = 1e30;\n"
	"		vec2  bestUV = vec2(0.0);\n"
	"		vec3  bestN  = vec3(0.0);\n"
	"		vec3  o = ro - base;\n"
	"\n"
	"		for (int i = 0; i < 2; i++) {\n"
	"			/* plane i = 0: x == z    plane i = 1: x == 1 - z */\n"
	"			vec3 n = (i == 0) ? vec3(1.0, 0.0, -1.0) : vec3(1.0, 0.0, 1.0);\n"
	"			float d = (i == 0) ? 0.0 : 1.0;\n"
	"			float denom = dot(rd, n);\n"
	"			if (abs(denom) < 1e-6) continue;\n"
	"\n"
	"			float t = (d - dot(o, n)) / denom;\n"
	"			if (t < tMin - 1e-4 || t > tMax + 1e-4 || t >= bestT) continue;\n"
	"\n"
	"			vec3 p = o + rd * t;\n"
	"			if (p.y < 0.0 || p.y > 1.0 || p.x < 0.0 || p.x > 1.0 || p.z < 0.0 || p.z > 1.0) continue;\n"
	"\n"
	"			vec2 uv = vec2(p.x, 1.0 - p.y);\n"
	"			if (!texelSolid(block, FACE_XMIN, uv)) continue;\n"
	"\n"
	"			bestT  = t;\n"
	"			bestUV = uv;\n"
	"			bestN  = normalize(n) * ((denom > 0.0) ? -1.0 : 1.0);\n"
	"		}\n"
	"		if (bestT >= 1e30) return false;\n"
	"\n"
	"		h.t = bestT; h.pos = ro + rd * bestT; h.normal = bestN; h.uv = bestUV;\n"
	"		h.block = block; h.face = FACE_XMIN; h.draw = uint(draw);\n"
	"		return true;\n"
	"	}\n"
	"\n"
	"	vec3 bmin = base + bi.minBB.xyz;\n"
	"	vec3 bmax = base + bi.maxBB.xyz;\n"
	"	vec3 t1 = (bmin - ro) * invRd;\n"
	"	vec3 t2 = (bmax - ro) * invRd;\n"
	"	vec3 tn = min(t1, t2);\n"
	"	vec3 tf = max(t1, t2);\n"
	"	float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"	float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"\n"
	"	/* small tolerance, since the DDA's accumulated cell boundaries drift slightly from the exact slab distances */\n"
	"	if (tExit < tEnter || tExit < tMin - 1e-4 || tEnter > tMax + 1e-4) return false;\n"
	"	/* ray starts inside this block - look through it (like backface culling does) */\n"
	"	if (tEnter < 0.0) return false;\n"
	"\n"
	"	vec3 normal; uint face;\n"
	"	if (tEnter == tn.x) {\n"
	"		normal = vec3(rd.x > 0.0 ? -1.0 : 1.0, 0.0, 0.0);\n"
	"		face   = rd.x > 0.0 ? FACE_XMIN : FACE_XMAX;\n"
	"	} else if (tEnter == tn.y) {\n"
	"		normal = vec3(0.0, rd.y > 0.0 ? -1.0 : 1.0, 0.0);\n"
	"		face   = rd.y > 0.0 ? FACE_YMIN : FACE_YMAX;\n"
	"	} else {\n"
	"		normal = vec3(0.0, 0.0, rd.z > 0.0 ? -1.0 : 1.0);\n"
	"		face   = rd.z > 0.0 ? FACE_ZMIN : FACE_ZMAX;\n"
	"	}\n"
	"\n"
	"	/* Faces shared with an identical neighbouring block aren't drawn (e.g. between two water */\n"
	"	/*  blocks, which are slightly lower than a full cell so rays can slip between them) */\n"
	"	if (draw != DRAW_TRANSPARENT_THICK && blockAt(c + ivec3(normal)) == block) return false;\n"
	"\n"
	"	vec3 local = clamp(ro + rd * tEnter - base, 0.0, 1.0);\n"
	"	vec2 uv    = faceUV(face, local);\n"
	"\n"
	"	if (draw == DRAW_TRANSPARENT || draw == DRAW_TRANSPARENT_THICK) {\n"
	"		if (!texelSolid(block, face, uv)) return false;\n"
	"	}\n"
	"\n"
	"	h.t = tEnter; h.pos = ro + rd * tEnter; h.normal = normal; h.uv = uv;\n"
	"	h.block = block; h.face = face; h.draw = uint(draw);\n"
	"	return true;\n"
	"}\n"
	"\n"
	"/* Walks the voxel grid along the ray. Returns true if any block geometry was hit within maxT */\n"
	"bool traceRay(vec3 ro, vec3 rd, float maxT, bool shadowRay, bool skipTranslucent, out Hit h) {\n"
	"	vec3  wsize = vec3(worldSize.xyz);\n"
	"	float tOffset = 0.0;\n"
	"	h.t = -1.0; h.block = 0u;\n"
	"\n"
	"	/* Clip the ray to the world bounds first */\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	if (any(lessThan(ro, vec3(0.0))) || any(greaterThanEqual(ro, wsize))) {\n"
	"		vec3 t1 = (vec3(0.0) - ro) * invRd;\n"
	"		vec3 t2 = (wsize      - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2);\n"
	"		vec3 tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < tEnter || tExit < 0.0 || tEnter > maxT) return false;\n"
	"\n"
	"		tOffset = max(tEnter, 0.0) + 1e-4;\n"
	"		ro     += rd * tOffset;\n"
	"		maxT   -= tOffset;\n"
	"	}\n"
	"\n"
	"	ivec3 c   = ivec3(floor(ro));\n"
	"	c = clamp(c, ivec3(0), worldSize.xyz - 1);\n"
	"	ivec3 stp = ivec3(sign(rd));\n"
	"	vec3  side = vec3(greaterThan(rd, vec3(0.0)));\n"
	"	float t = 0.0;\n"
	"	ivec3 lastCoarse = ivec3(-1);\n"
	"	bool  coarseEmpty = false;\n"
	"\n"
	"	for (int i = 0; i < MAX_DDA_STEPS; i++) {\n"
	"		ivec3 cc = c >> COARSE_SHIFT;\n"
	"		if (cc != lastCoarse) {\n"
	"			lastCoarse  = cc;\n"
	"			coarseEmpty = coarseAt(cc) == 0u;\n"
	"		}\n"
	"\n"
	"		if (coarseEmpty) {\n"
	"			/* Whole 8x8x8 region is air - jump straight to where the ray leaves it */\n"
	"			vec3 cmin = vec3(cc << COARSE_SHIFT);\n"
	"			vec3 tf = max((cmin - ro) * invRd, (cmin + COARSE_SIZE - ro) * invRd);\n"
	"			if (rd.x == 0.0) tf.x = 1e30;\n"
	"			if (rd.y == 0.0) tf.y = 1e30;\n"
	"			if (rd.z == 0.0) tf.z = 1e30;\n"
	"			t = min(min(tf.x, tf.y), tf.z);\n"
	"			if (t > maxT) return false;\n"
	"\n"
	"			ivec3 lo = cc << COARSE_SHIFT;\n"
	"			c = clamp(ivec3(floor(ro + rd * t)), lo, lo + int(COARSE_SIZE) - 1);\n"
	"			/* step the axis that was crossed into the neighbouring region exactly */\n"
	"			if (t == tf.x)      c.x = (stp.x > 0) ? lo.x + int(COARSE_SIZE) : lo.x - 1;\n"
	"			else if (t == tf.y) c.y = (stp.y > 0) ? lo.y + int(COARSE_SIZE) : lo.y - 1;\n"
	"			else                c.z = (stp.z > 0) ? lo.z + int(COARSE_SIZE) : lo.z - 1;\n"
	"\n"
	"			if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"			continue;\n"
	"		}\n"
	"\n"
	"		/* Distance to each of the three cell boundaries in front of the ray. Recomputed from the */\n"
	"		/*  cell coordinates every step, so no floating point drift accumulates between the cell */\n"
	"		/*  walk and the exact slab tests in hitCell (drift caused cracks between blocks) */\n"
	"		vec3 tNext = (vec3(c) + side - ro) * invRd;\n"
	"		if (rd.x == 0.0) tNext.x = 1e30;\n"
	"		if (rd.y == 0.0) tNext.y = 1e30;\n"
	"		if (rd.z == 0.0) tNext.z = 1e30;\n"
	"		float tExit = min(min(tNext.x, tNext.y), tNext.z);\n"
	"		uint  b = blockAt(c);\n"
	"\n"
	"		if (b != 0u) {\n"
	"			if (hitCell(c, b, ro, rd, invRd, t, min(tExit, maxT), shadowRay, skipTranslucent, h)) {\n"
	"				h.t += tOffset;\n"
	"				return true;\n"
	"			}\n"
	"		}\n"
	"\n"
	"		if (tNext.x < tNext.y && tNext.x < tNext.z) {\n"
	"			c.x += stp.x;\n"
	"		} else if (tNext.y < tNext.z) {\n"
	"			c.y += stp.y;\n"
	"		} else {\n"
	"			c.z += stp.z;\n"
	"		}\n"
	"		t = tExit;\n"
	"\n"
	"		if (t > maxT) return false;\n"
	"		if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* Colour of a face when in direct sunlight, following the classic per-face shading */\n"
	"vec3 sunlitColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return sunCol.rgb;\n"
	"	if (n.y < -0.5) return sunYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return sunXSide.rgb;\n"
	"	return sunZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Colour of a face when only lit by the sky */\n"
	"vec3 shadowColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return shadowCol.rgb;\n"
	"	if (n.y < -0.5) return shadowYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return shadowXSide.rgb;\n"
	"	return shadowZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Moller-Trumbore ray/triangle test, both sides */\n"
	"bool hitTriangle(vec3 ro, vec3 rd, vec3 a, vec3 b, vec3 c, float maxT) {\n"
	"	vec3 e1 = b - a, e2 = c - a;\n"
	"	vec3 pv = cross(rd, e2);\n"
	"	float det = dot(e1, pv);\n"
	"	if (abs(det) < 1e-7) return false;\n"
	"	float inv = 1.0 / det;\n"
	"	vec3 tv = ro - a;\n"
	"	float u = dot(tv, pv) * inv;\n"
	"	if (u < 0.0 || u > 1.0) return false;\n"
	"	vec3 qv = cross(tv, e1);\n"
	"	float v = dot(rd, qv) * inv;\n"
	"	if (v < 0.0 || u + v > 1.0) return false;\n"
	"	float t = dot(e2, qv) * inv;\n"
	"	return t > 1e-3 && t < maxT;\n"
	"}\n"
	"\n"
	"/* Whether the ray hits any entity (player) model recorded this frame */\n"
	"bool hitEntities(vec3 ro, vec3 rd, float maxT) {\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	for (int i = 0; i < window.z; i++) {\n"
	"		EntityInfo e = entities[i];\n"
	"		vec3 t1 = (e.bbMin.xyz - ro) * invRd;\n"
	"		vec3 t2 = (e.bbMax.xyz - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2), tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < max(tEnter, 0.0) || tEnter > maxT) continue;\n"
	"\n"
	"		uint first = e.range.x, count = e.range.y;\n"
	"		for (uint q = 0u; q < count; q++) {\n"
	"			uint b = (first + q) * 4u;\n"
	"			vec3 v0 = quadVerts[b].xyz, v1 = quadVerts[b + 1u].xyz;\n"
	"			vec3 v2 = quadVerts[b + 2u].xyz, v3 = quadVerts[b + 3u].xyz;\n"
	"			if (hitTriangle(ro, rd, v0, v1, v2, maxT) || hitTriangle(ro, rd, v0, v2, v3, maxT)) return true;\n"
	"		}\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* How much sunlight gets through the clouds along L from p (1 = no cloud) */\n"
	"float cloudShadow(vec3 p, vec3 L) {\n"
	"	if (clouds.w < 0.5 || L.y <= 0.0 || p.y >= clouds.x) return 1.0;\n"
	"	float t  = (clouds.x - p.y) / L.y;\n"
	"	vec2  xz = p.xz + L.xz * t;\n"
	"	/* same mapping as the cloud layer: 2048 blocks per texture repeat, scrolling along U */\n"
	"	vec2  uv = fract(vec2(xz.x / 2048.0 + clouds.y, xz.y / 2048.0));\n"
	"	float a  = textureLod(cloudsTex, uv, 0.0).a;\n"
	"	return 1.0 - a * clouds.z;\n"
	"}\n"
	"\n"
	"/* Direct sunlight contribution for a surface point, tracing a shadow ray towards the sun */\n"
	"vec3 directSun(vec3 p, vec3 n, vec3 L) {\n"
	"	float ndl = dot(n, L);\n"
	"	if (ndl <= 0.0) return vec3(0.0);\n"
	"\n"
	"	Hit sh;\n"
	"	if (traceRay(p, L, 512.0, true, false, sh)) return vec3(0.0);\n"
	"	if (window.z > 0 && hitEntities(p, L, 64.0)) return vec3(0.0);\n"
	"\n"
	"	/* Normalise so that an upward facing face receives the full classic sun colour */\n"
	"	float f = clamp(ndl / max(L.y, 0.2), 0.0, 1.0) * cloudShadow(p, L);\n"
	"	return max(sunlitColour(n) - shadowColour(n), vec3(0.0)) * f;\n"
	"}\n"
	"\n"
	"/* Random number helpers */\n"
	"uint pcgHash(uint v) {\n"
	"	uint state = v * 747796405u + 2891336453u;\n"
	"	uint word  = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;\n"
	"	return (word >> 22u) ^ word;\n"
	"}\n"
	"\n"
	"float rand(inout uint seed) {\n"
	"	seed = pcgHash(seed);\n"
	"	return float(seed) * (1.0 / 4294967296.0);\n"
	"}\n"
	"\n"
	"/* Cosine weighted direction in the hemisphere around n */\n"
	"vec3 cosineSample(vec3 n, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float sr2 = sqrt(r2);\n"
	"	vec3 t = abs(n.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, n));\n"
	"	vec3 v = cross(n, u);\n"
	"	return normalize(u * (cos(phi) * sr2) + v * (sin(phi) * sr2) + n * sqrt(max(0.0, 1.0 - r2)));\n"
	"}\n"
	"\n"
	"/* Random direction inside a cone around dir, tan of half angle = tanRadius */\n"
	"vec3 coneSample(vec3 dir, float tanRadius, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float r   = tanRadius * sqrt(r2);\n"
	"	vec3 t = abs(dir.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, dir));\n"
	"	vec3 v = cross(dir, u);\n"
	"	return normalize(dir + u * (cos(phi) * r) + v * (sin(phi) * r));\n"
	"}\n"
	"\n"
	"/* Light received from emitting blocks (lava, lamps...) by explicitly sampling one of them.\n"
	"   Picks an emitter with probability proportional to 1/distance^2, then traces a ray to it.\n"
	"   Noisy per frame, but the temporal accumulation and blur average it out. */\n"
	"vec3 emitterLight(vec3 p, vec3 n, inout uint seed) {\n"
	"	int count = window.w;\n"
	"	if (count == 0) return vec3(0.0);\n"
	"\n"
	"	float wsum = 0.0, chosenW = 0.0;\n"
	"	int chosen = -1;\n"
	"	for (int i = 0; i < count; i++) {\n"
	"		vec3 d = vec3(emitters[i].xyz) + 0.5 - p;\n"
	"		float d2 = dot(d, d);\n"
	"		if (d2 > 32.0 * 32.0 || dot(d, n) <= 0.0) continue;\n"
	"\n"
	"		float w = 1.0 / max(d2, 1.0);\n"
	"		wsum += w;\n"
	"		if (rand(seed) * wsum < w) { chosen = i; chosenW = w; }\n"
	"	}\n"
	"	if (chosen < 0) return vec3(0.0);\n"
	"\n"
	"	vec3  d    = vec3(emitters[chosen].xyz) + 0.5 - p;\n"
	"	float dist = length(d);\n"
	"	vec3  dir  = d / dist;\n"
	"	Hit eh;\n"
	"	if (!traceRay(p, dir, dist + 1.0, false, true, eh)) return vec3(0.0);\n"
	"	/* must have reached the emitter itself, not something in between */\n"
	"	if (ivec3(floor(eh.pos - eh.normal * 0.5)) != emitters[chosen].xyz) return vec3(0.0);\n"
	"\n"
	"	vec3  Le   = sampleTile(tileFor(eh.block, eh.face), eh.uv, 4.0).rgb * blocks[eh.block].tint.rgb * fogParams.z;\n"
	"	float cosR = max(dot(n, dir), 0.0);\n"
	"	float cosE = max(dot(-dir, eh.normal), 0.0);\n"
	"	float falloff = 1.0 / max(dist * dist, 1.0);\n"
	"	return Le * cosR * cosE * falloff * (wsum / chosenW) / 3.14159265;\n"
	"}\n"
	"\n"
	"/* Combines the traced lighting terms into the final colour, applies fog to\n"
	"   match the rasterised sky/clouds/entities, and writes depth so that\n"
	"   everything the game draws afterwards is occluded correctly. */\n"
	"layout(binding = 6)  uniform sampler2D gbufTex;\n"
	"layout(binding = 7)  uniform sampler2D albedoTex;\n"
	"layout(binding = 8)  uniform sampler2D directTex;\n"
	"layout(binding = 9)  uniform sampler2D indirectTex;\n"
	"layout(binding = 10) uniform sampler2D waterTex;\n"
	"layout(binding = 11) uniform sampler2D normalTex;\n"
	"\n"
	"out vec4 fragColour;\n"
	"\n"
	"void main() {\n"
	"	/* The trace buffers may be smaller than the window (rt-scale option) */\n"
	"	ivec2 px = ivec2(vec2(gl_FragCoord.xy) * vec2(screen.xy) / vec2(window.xy));\n"
	"	px = clamp(px, ivec2(0), screen.xy - 1);\n"
	"	vec4 g = texelFetch(gbufTex, px, 0);\n"
	"	if (g.w < 0.0) discard;\n"
	"\n"
	"	vec3 albedo   = texelFetch(albedoTex,   px, 0).rgb;\n"
	"	vec3 direct   = texelFetch(directTex,   px, 0).rgb;\n"
	"	vec3 indirect = texelFetch(indirectTex, px, 0).rgb;\n"
	"	vec3 colour   = albedo * (direct + indirect);\n"
	"\n"
	"	/* rt-debug option: view individual lighting terms */\n"
	"	int debug = int(fogParams.w);\n"
	"	if (debug != 0) {\n"
	"		vec4 n = texelFetch(normalTex, px, 0);\n"
	"		if (debug == 1) colour = direct;\n"
	"		if (debug == 2) colour = indirect;\n"
	"		if (debug == 3) colour = albedo;\n"
	"		if (debug == 4) colour = n.xyz * 0.5 + 0.5;\n"
	"		if (debug == 5) colour = texelFetch(waterTex, px, 0).rgb;\n"
	"		if (debug == 6) colour = vec3(fract(g.w / 16.0));\n"
	"		if (debug == 7) colour = vec3(n.w / 64.0);\n"
	"		vec4 dclip = viewProj * vec4(g.xyz, 1.0);\n"
	"		gl_FragDepth = clamp((dclip.z / dclip.w) * 0.5 + 0.5, 0.0, 1.0);\n"
	"		fragColour = vec4(colour, 1.0);\n"
	"		return;\n"
	"	}\n"
	"\n"
	"	/* Fog, using eye space depth like the fixed function pipeline does */\n"
	"	vec4  eye = view * vec4(g.xyz, 1.0);\n"
	"	float fz  = abs(eye.z);\n"
	"	float f;\n"
	"	if (fogCol.w > 0.0) {\n"
	"		f = exp(-fogCol.w * fz);\n"
	"	} else {\n"
	"		f = clamp((fogParams.x - fz) / fogParams.x, 0.0, 1.0);\n"
	"	}\n"
	"	colour = mix(fogCol.rgb, colour, f);\n"
	"\n"
	"	vec4 clip = viewProj * vec4(g.xyz, 1.0);\n"
	"	gl_FragDepth = clamp((clip.z / clip.w) * 0.5 + 0.5, 0.0, 1.0);\n"
	"	fragColour = vec4(colour, 1.0);\n"
	"}\n"
	"\n";

static const char* const RT_WATER_FS =
	"#version 430\n"
	"/* Shared code for the ClassiCube GPU voxel path tracer (see src/RayTracer.c)\n"
	"   The world is traced directly as a voxel grid using a 3D DDA walk, so no\n"
	"   acceleration structure has to be built or maintained on block changes.\n"
	"   Copyright 2014-2025 ClassiCube | Licensed under BSD-3 */\n"
	"\n"
	"/* Must match struct RTParams in RayTracer.c (std140 layout, vec4/mat4 only) */\n"
	"layout(std140, binding = 0) uniform Params {\n"
	"	mat4  invViewProj;  /* clip space -> world space */\n"
	"	mat4  viewProj;     /* world space -> clip space (current frame) */\n"
	"	mat4  prevViewProj; /* world space -> clip space (previous frame) */\n"
	"	mat4  view;         /* world space -> eye space */\n"
	"	vec4  camPos;       /* xyz = camera position, w = time in seconds */\n"
	"	vec4  sunDir;       /* xyz = direction towards the sun, w = tan(sun angular radius) */\n"
	"	vec4  sunCol, sunXSide, sunZSide, sunYMin;\n"
	"	vec4  shadowCol, shadowXSide, shadowZSide, shadowYMin;\n"
	"	vec4  skyCol;       /* rgb = colour seen by rays that escape the world */\n"
	"	vec4  fogCol;       /* rgb = fog colour, w = exp fog density (0 = linear fog) */\n"
	"	vec4  fogParams;    /* x = linear fog end, y = minimum ambient, z = emissive strength, w = unused */\n"
	"	ivec4 worldSize;    /* xyz = world dimensions */\n"
	"	ivec4 screen;       /* xy = render size, z = frame index, w = flags */\n"
	"	ivec4 atlas;        /* x = atlas1D shift, y = atlas1D mask, z = atlas count, w = tile size in pixels */\n"
	"	vec4  misc;         /* x = atlas1D V per tile, y = max primary distance, z = GI ray distance, w = pixel angular size */\n"
	"	ivec4 window;       /* xy = window size in pixels (render size may be smaller, see rt-scale), z = entity count, w = emitter count */\n"
	"	vec4  clouds;       /* x = clouds height, y = cloud texture scroll offset, z = shadow strength, w = enabled */\n"
	"};\n"
	"\n"
	"#define FLAG_GI          1\n"
	"#define FLAG_REFLECTIONS 2\n"
	"#define FLAG_SOFT_SHADOWS 4\n"
	"\n"
	"/* Must match struct RTBlockInfo in RayTracer.c */\n"
	"struct BlockInfo {\n"
	"	vec4  minBB;  /* xyz = min bounds, w = draw type */\n"
	"	vec4  maxBB;  /* xyz = max bounds, w = flags */\n"
	"	uvec4 texA;   /* tile ids for faces XMIN, XMAX, ZMIN, ZMAX */\n"
	"	uvec4 texB;   /* tile ids for faces YMIN, YMAX, then unused */\n"
	"	vec4  tint;   /* rgb = colour multiplier, w = 1 if block is full bright */\n"
	"};\n"
	"\n"
	"layout(std430, binding = 1) readonly buffer BlockTable { BlockInfo blocks[]; };\n"
	"\n"
	"layout(binding = 1) uniform usampler3D worldTex;\n"
	"layout(binding = 2) uniform sampler2D atlas0;\n"
	"layout(binding = 3) uniform sampler2D atlas1;\n"
	"layout(binding = 4) uniform sampler2D atlas2;\n"
	"layout(binding = 5) uniform sampler2D atlas3;\n"
	"/* 1 byte per 8x8x8 region of the world: 0 if the region is entirely air, so rays can skip it */\n"
	"layout(binding = 14) uniform usampler3D coarseTex;\n"
	"#define COARSE_SHIFT 3\n"
	"#define COARSE_SIZE  8.0\n"
	"/* The game's cloud texture, for cloud shadows */\n"
	"layout(binding = 15) uniform sampler2D cloudsTex;\n"
	"\n"
	"/* Entity models drawn this frame, recorded as world space quads (must match RTEntity in RayTracer.c) */\n"
	"struct EntityInfo {\n"
	"	vec4  bbMin;\n"
	"	vec4  bbMax;\n"
	"	uvec4 range;  /* x = first quad, y = quad count */\n"
	"};\n"
	"layout(std430, binding = 2) readonly buffer EntityTable { EntityInfo entities[]; };\n"
	"layout(std430, binding = 3) readonly buffer EntityQuads { vec4 quadVerts[]; };\n"
	"/* Light emitting blocks near the camera: xyz = block position, w = block id */\n"
	"layout(std430, binding = 4) readonly buffer EmitterTable { ivec4 emitters[]; };\n"
	"\n"
	"#define DRAW_OPAQUE            0\n"
	"#define DRAW_TRANSPARENT       1\n"
	"#define DRAW_TRANSPARENT_THICK 2\n"
	"#define DRAW_TRANSLUCENT       3\n"
	"#define DRAW_GAS               4\n"
	"#define DRAW_SPRITE            5\n"
	"\n"
	"#define BLOCKFLAG_BLOCKS_LIGHT 1\n"
	"\n"
	"#define FACE_XMIN 0\n"
	"#define FACE_XMAX 1\n"
	"#define FACE_ZMIN 2\n"
	"#define FACE_ZMAX 3\n"
	"#define FACE_YMIN 4\n"
	"#define FACE_YMAX 5\n"
	"\n"
	"#define MAX_DDA_STEPS 1024\n"
	"\n"
	"struct Hit {\n"
	"	vec3  pos;     /* world space hit position */\n"
	"	vec3  normal;  /* geometric normal facing the ray */\n"
	"	vec2  uv;      /* texture coordinates within the tile */\n"
	"	float t;       /* distance along the ray */\n"
	"	uint  block;   /* block id that was hit */\n"
	"	uint  face;    /* FACE_ constant of hit face */\n"
	"	uint  draw;    /* draw type of hit block */\n"
	"};\n"
	"\n"
	"int  drawType(uint block)  { return int(blocks[block].minBB.w); }\n"
	"bool blocksLight(uint block) { return (int(blocks[block].maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) != 0; }\n"
	"bool fullBright(uint block) { return blocks[block].tint.w > 0.5; }\n"
	"\n"
	"uint tileFor(uint block, uint face) {\n"
	"	/* NOTE: NVIDIA's compiler rejects a constant out of range index even in a branch that */\n"
	"	/*  can't be taken, so the index must stay in range for every possible face value */\n"
	"	uvec4 tiles = (face < 4u) ? blocks[block].texA : blocks[block].texB;\n"
	"	return tiles[face & 3u];\n"
	"}\n"
	"\n"
	"uint coarseAt(ivec3 cc) {\n"
	"	return texelFetch(coarseTex, ivec3(cc.x, cc.z, cc.y), 0).r;\n"
	"}\n"
	"\n"
	"uint blockAt(ivec3 p) {\n"
	"	if (any(lessThan(p, ivec3(0))) || any(greaterThanEqual(p, worldSize.xyz))) return 0u;\n"
	"	/* world texture is stored as (x, z, y) so that height is the depth axis */\n"
	"	return texelFetch(worldTex, ivec3(p.x, p.z, p.y), 0).r;\n"
	"}\n"
	"\n"
	"vec4 sampleTile(uint texLoc, vec2 uv, float lod) {\n"
	"	uint idx = texLoc >> uint(atlas.x);\n"
	"	uint row = texLoc &  uint(atlas.y);\n"
	"	/* keep slightly inside the tile, so mipmaps/filtering don't bleed neighbouring tiles */\n"
	"	float pad = 0.5 / float(atlas.w);\n"
	"	uv = clamp(uv, vec2(pad), vec2(1.0 - pad));\n"
	"	vec2 st = vec2(uv.x, (float(row) + uv.y) * misc.x);\n"
	"\n"
	"	if (idx == 0u) return textureLod(atlas0, st, lod);\n"
	"	if (idx == 1u) return textureLod(atlas1, st, lod);\n"
	"	if (idx == 2u) return textureLod(atlas2, st, lod);\n"
	"	return textureLod(atlas3, st, lod);\n"
	"}\n"
	"\n"
	"/* Texture coordinates for a point on the given face, matching Drawer.c orientation */\n"
	"vec2 faceUV(uint face, vec3 local) {\n"
	"	if (face == FACE_XMIN) return vec2(local.z,       1.0 - local.y);\n"
	"	if (face == FACE_XMAX) return vec2(1.0 - local.z, 1.0 - local.y);\n"
	"	if (face == FACE_ZMIN) return vec2(1.0 - local.x, 1.0 - local.y);\n"
	"	if (face == FACE_ZMAX) return vec2(local.x,       1.0 - local.y);\n"
	"	return vec2(local.x, local.z); /* YMIN / YMAX */\n"
	"}\n"
	"\n"
	"/* Whether a texel of the given tile should be treated as solid for alpha tested blocks */\n"
	"bool texelSolid(uint block, uint face, vec2 uv) {\n"
	"	return sampleTile(tileFor(block, face), uv, 0.0).a > 0.5;\n"
	"}\n"
	"\n"
	"/* Intersects the ray with the geometry of one block inside cell c.\n"
	"   tMin/tMax bound the ray segment that lies inside the cell */\n"
	"bool hitCell(ivec3 c, uint block, vec3 ro, vec3 rd, vec3 invRd, float tMin, float tMax, bool shadowRay, bool skipTranslucent, inout Hit h) {\n"
	"	BlockInfo bi = blocks[block];\n"
	"	int  draw = int(bi.minBB.w);\n"
	"	vec3 base = vec3(c);\n"
	"\n"
	"	if (draw == DRAW_GAS) return false;\n"
	"	if (shadowRay && (int(bi.maxBB.w) & BLOCKFLAG_BLOCKS_LIGHT) == 0) return false;\n"
	"	if (draw == DRAW_TRANSLUCENT && skipTranslucent) return false;\n"
	"\n"
	"	if (draw == DRAW_SPRITE) {\n"
	"		/* Two crossed quads along the diagonals of the cell */\n"
	"		float bestT = 1e30;\n"
	"		vec2  bestUV = vec2(0.0);\n"
	"		vec3  bestN  = vec3(0.0);\n"
	"		vec3  o = ro - base;\n"
	"\n"
	"		for (int i = 0; i < 2; i++) {\n"
	"			/* plane i = 0: x == z    plane i = 1: x == 1 - z */\n"
	"			vec3 n = (i == 0) ? vec3(1.0, 0.0, -1.0) : vec3(1.0, 0.0, 1.0);\n"
	"			float d = (i == 0) ? 0.0 : 1.0;\n"
	"			float denom = dot(rd, n);\n"
	"			if (abs(denom) < 1e-6) continue;\n"
	"\n"
	"			float t = (d - dot(o, n)) / denom;\n"
	"			if (t < tMin - 1e-4 || t > tMax + 1e-4 || t >= bestT) continue;\n"
	"\n"
	"			vec3 p = o + rd * t;\n"
	"			if (p.y < 0.0 || p.y > 1.0 || p.x < 0.0 || p.x > 1.0 || p.z < 0.0 || p.z > 1.0) continue;\n"
	"\n"
	"			vec2 uv = vec2(p.x, 1.0 - p.y);\n"
	"			if (!texelSolid(block, FACE_XMIN, uv)) continue;\n"
	"\n"
	"			bestT  = t;\n"
	"			bestUV = uv;\n"
	"			bestN  = normalize(n) * ((denom > 0.0) ? -1.0 : 1.0);\n"
	"		}\n"
	"		if (bestT >= 1e30) return false;\n"
	"\n"
	"		h.t = bestT; h.pos = ro + rd * bestT; h.normal = bestN; h.uv = bestUV;\n"
	"		h.block = block; h.face = FACE_XMIN; h.draw = uint(draw);\n"
	"		return true;\n"
	"	}\n"
	"\n"
	"	vec3 bmin = base + bi.minBB.xyz;\n"
	"	vec3 bmax = base + bi.maxBB.xyz;\n"
	"	vec3 t1 = (bmin - ro) * invRd;\n"
	"	vec3 t2 = (bmax - ro) * invRd;\n"
	"	vec3 tn = min(t1, t2);\n"
	"	vec3 tf = max(t1, t2);\n"
	"	float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"	float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"\n"
	"	/* small tolerance, since the DDA's accumulated cell boundaries drift slightly from the exact slab distances */\n"
	"	if (tExit < tEnter || tExit < tMin - 1e-4 || tEnter > tMax + 1e-4) return false;\n"
	"	/* ray starts inside this block - look through it (like backface culling does) */\n"
	"	if (tEnter < 0.0) return false;\n"
	"\n"
	"	vec3 normal; uint face;\n"
	"	if (tEnter == tn.x) {\n"
	"		normal = vec3(rd.x > 0.0 ? -1.0 : 1.0, 0.0, 0.0);\n"
	"		face   = rd.x > 0.0 ? FACE_XMIN : FACE_XMAX;\n"
	"	} else if (tEnter == tn.y) {\n"
	"		normal = vec3(0.0, rd.y > 0.0 ? -1.0 : 1.0, 0.0);\n"
	"		face   = rd.y > 0.0 ? FACE_YMIN : FACE_YMAX;\n"
	"	} else {\n"
	"		normal = vec3(0.0, 0.0, rd.z > 0.0 ? -1.0 : 1.0);\n"
	"		face   = rd.z > 0.0 ? FACE_ZMIN : FACE_ZMAX;\n"
	"	}\n"
	"\n"
	"	/* Faces shared with an identical neighbouring block aren't drawn (e.g. between two water */\n"
	"	/*  blocks, which are slightly lower than a full cell so rays can slip between them) */\n"
	"	if (draw != DRAW_TRANSPARENT_THICK && blockAt(c + ivec3(normal)) == block) return false;\n"
	"\n"
	"	vec3 local = clamp(ro + rd * tEnter - base, 0.0, 1.0);\n"
	"	vec2 uv    = faceUV(face, local);\n"
	"\n"
	"	if (draw == DRAW_TRANSPARENT || draw == DRAW_TRANSPARENT_THICK) {\n"
	"		if (!texelSolid(block, face, uv)) return false;\n"
	"	}\n"
	"\n"
	"	h.t = tEnter; h.pos = ro + rd * tEnter; h.normal = normal; h.uv = uv;\n"
	"	h.block = block; h.face = face; h.draw = uint(draw);\n"
	"	return true;\n"
	"}\n"
	"\n"
	"/* Walks the voxel grid along the ray. Returns true if any block geometry was hit within maxT */\n"
	"bool traceRay(vec3 ro, vec3 rd, float maxT, bool shadowRay, bool skipTranslucent, out Hit h) {\n"
	"	vec3  wsize = vec3(worldSize.xyz);\n"
	"	float tOffset = 0.0;\n"
	"	h.t = -1.0; h.block = 0u;\n"
	"\n"
	"	/* Clip the ray to the world bounds first */\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	if (any(lessThan(ro, vec3(0.0))) || any(greaterThanEqual(ro, wsize))) {\n"
	"		vec3 t1 = (vec3(0.0) - ro) * invRd;\n"
	"		vec3 t2 = (wsize      - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2);\n"
	"		vec3 tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < tEnter || tExit < 0.0 || tEnter > maxT) return false;\n"
	"\n"
	"		tOffset = max(tEnter, 0.0) + 1e-4;\n"
	"		ro     += rd * tOffset;\n"
	"		maxT   -= tOffset;\n"
	"	}\n"
	"\n"
	"	ivec3 c   = ivec3(floor(ro));\n"
	"	c = clamp(c, ivec3(0), worldSize.xyz - 1);\n"
	"	ivec3 stp = ivec3(sign(rd));\n"
	"	vec3  side = vec3(greaterThan(rd, vec3(0.0)));\n"
	"	float t = 0.0;\n"
	"	ivec3 lastCoarse = ivec3(-1);\n"
	"	bool  coarseEmpty = false;\n"
	"\n"
	"	for (int i = 0; i < MAX_DDA_STEPS; i++) {\n"
	"		ivec3 cc = c >> COARSE_SHIFT;\n"
	"		if (cc != lastCoarse) {\n"
	"			lastCoarse  = cc;\n"
	"			coarseEmpty = coarseAt(cc) == 0u;\n"
	"		}\n"
	"\n"
	"		if (coarseEmpty) {\n"
	"			/* Whole 8x8x8 region is air - jump straight to where the ray leaves it */\n"
	"			vec3 cmin = vec3(cc << COARSE_SHIFT);\n"
	"			vec3 tf = max((cmin - ro) * invRd, (cmin + COARSE_SIZE - ro) * invRd);\n"
	"			if (rd.x == 0.0) tf.x = 1e30;\n"
	"			if (rd.y == 0.0) tf.y = 1e30;\n"
	"			if (rd.z == 0.0) tf.z = 1e30;\n"
	"			t = min(min(tf.x, tf.y), tf.z);\n"
	"			if (t > maxT) return false;\n"
	"\n"
	"			ivec3 lo = cc << COARSE_SHIFT;\n"
	"			c = clamp(ivec3(floor(ro + rd * t)), lo, lo + int(COARSE_SIZE) - 1);\n"
	"			/* step the axis that was crossed into the neighbouring region exactly */\n"
	"			if (t == tf.x)      c.x = (stp.x > 0) ? lo.x + int(COARSE_SIZE) : lo.x - 1;\n"
	"			else if (t == tf.y) c.y = (stp.y > 0) ? lo.y + int(COARSE_SIZE) : lo.y - 1;\n"
	"			else                c.z = (stp.z > 0) ? lo.z + int(COARSE_SIZE) : lo.z - 1;\n"
	"\n"
	"			if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"			continue;\n"
	"		}\n"
	"\n"
	"		/* Distance to each of the three cell boundaries in front of the ray. Recomputed from the */\n"
	"		/*  cell coordinates every step, so no floating point drift accumulates between the cell */\n"
	"		/*  walk and the exact slab tests in hitCell (drift caused cracks between blocks) */\n"
	"		vec3 tNext = (vec3(c) + side - ro) * invRd;\n"
	"		if (rd.x == 0.0) tNext.x = 1e30;\n"
	"		if (rd.y == 0.0) tNext.y = 1e30;\n"
	"		if (rd.z == 0.0) tNext.z = 1e30;\n"
	"		float tExit = min(min(tNext.x, tNext.y), tNext.z);\n"
	"		uint  b = blockAt(c);\n"
	"\n"
	"		if (b != 0u) {\n"
	"			if (hitCell(c, b, ro, rd, invRd, t, min(tExit, maxT), shadowRay, skipTranslucent, h)) {\n"
	"				h.t += tOffset;\n"
	"				return true;\n"
	"			}\n"
	"		}\n"
	"\n"
	"		if (tNext.x < tNext.y && tNext.x < tNext.z) {\n"
	"			c.x += stp.x;\n"
	"		} else if (tNext.y < tNext.z) {\n"
	"			c.y += stp.y;\n"
	"		} else {\n"
	"			c.z += stp.z;\n"
	"		}\n"
	"		t = tExit;\n"
	"\n"
	"		if (t > maxT) return false;\n"
	"		if (any(lessThan(c, ivec3(0))) || any(greaterThanEqual(c, worldSize.xyz))) return false;\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* Colour of a face when in direct sunlight, following the classic per-face shading */\n"
	"vec3 sunlitColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return sunCol.rgb;\n"
	"	if (n.y < -0.5) return sunYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return sunXSide.rgb;\n"
	"	return sunZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Colour of a face when only lit by the sky */\n"
	"vec3 shadowColour(vec3 n) {\n"
	"	if (n.y > 0.5)  return shadowCol.rgb;\n"
	"	if (n.y < -0.5) return shadowYMin.rgb;\n"
	"	if (abs(n.x) > 0.5) return shadowXSide.rgb;\n"
	"	return shadowZSide.rgb;\n"
	"}\n"
	"\n"
	"/* Moller-Trumbore ray/triangle test, both sides */\n"
	"bool hitTriangle(vec3 ro, vec3 rd, vec3 a, vec3 b, vec3 c, float maxT) {\n"
	"	vec3 e1 = b - a, e2 = c - a;\n"
	"	vec3 pv = cross(rd, e2);\n"
	"	float det = dot(e1, pv);\n"
	"	if (abs(det) < 1e-7) return false;\n"
	"	float inv = 1.0 / det;\n"
	"	vec3 tv = ro - a;\n"
	"	float u = dot(tv, pv) * inv;\n"
	"	if (u < 0.0 || u > 1.0) return false;\n"
	"	vec3 qv = cross(tv, e1);\n"
	"	float v = dot(rd, qv) * inv;\n"
	"	if (v < 0.0 || u + v > 1.0) return false;\n"
	"	float t = dot(e2, qv) * inv;\n"
	"	return t > 1e-3 && t < maxT;\n"
	"}\n"
	"\n"
	"/* Whether the ray hits any entity (player) model recorded this frame */\n"
	"bool hitEntities(vec3 ro, vec3 rd, float maxT) {\n"
	"	vec3 invRd = 1.0 / rd;\n"
	"	for (int i = 0; i < window.z; i++) {\n"
	"		EntityInfo e = entities[i];\n"
	"		vec3 t1 = (e.bbMin.xyz - ro) * invRd;\n"
	"		vec3 t2 = (e.bbMax.xyz - ro) * invRd;\n"
	"		vec3 tn = min(t1, t2), tf = max(t1, t2);\n"
	"		float tEnter = max(max(tn.x, tn.y), tn.z);\n"
	"		float tExit  = min(min(tf.x, tf.y), tf.z);\n"
	"		if (tExit < max(tEnter, 0.0) || tEnter > maxT) continue;\n"
	"\n"
	"		uint first = e.range.x, count = e.range.y;\n"
	"		for (uint q = 0u; q < count; q++) {\n"
	"			uint b = (first + q) * 4u;\n"
	"			vec3 v0 = quadVerts[b].xyz, v1 = quadVerts[b + 1u].xyz;\n"
	"			vec3 v2 = quadVerts[b + 2u].xyz, v3 = quadVerts[b + 3u].xyz;\n"
	"			if (hitTriangle(ro, rd, v0, v1, v2, maxT) || hitTriangle(ro, rd, v0, v2, v3, maxT)) return true;\n"
	"		}\n"
	"	}\n"
	"	return false;\n"
	"}\n"
	"\n"
	"/* How much sunlight gets through the clouds along L from p (1 = no cloud) */\n"
	"float cloudShadow(vec3 p, vec3 L) {\n"
	"	if (clouds.w < 0.5 || L.y <= 0.0 || p.y >= clouds.x) return 1.0;\n"
	"	float t  = (clouds.x - p.y) / L.y;\n"
	"	vec2  xz = p.xz + L.xz * t;\n"
	"	/* same mapping as the cloud layer: 2048 blocks per texture repeat, scrolling along U */\n"
	"	vec2  uv = fract(vec2(xz.x / 2048.0 + clouds.y, xz.y / 2048.0));\n"
	"	float a  = textureLod(cloudsTex, uv, 0.0).a;\n"
	"	return 1.0 - a * clouds.z;\n"
	"}\n"
	"\n"
	"/* Direct sunlight contribution for a surface point, tracing a shadow ray towards the sun */\n"
	"vec3 directSun(vec3 p, vec3 n, vec3 L) {\n"
	"	float ndl = dot(n, L);\n"
	"	if (ndl <= 0.0) return vec3(0.0);\n"
	"\n"
	"	Hit sh;\n"
	"	if (traceRay(p, L, 512.0, true, false, sh)) return vec3(0.0);\n"
	"	if (window.z > 0 && hitEntities(p, L, 64.0)) return vec3(0.0);\n"
	"\n"
	"	/* Normalise so that an upward facing face receives the full classic sun colour */\n"
	"	float f = clamp(ndl / max(L.y, 0.2), 0.0, 1.0) * cloudShadow(p, L);\n"
	"	return max(sunlitColour(n) - shadowColour(n), vec3(0.0)) * f;\n"
	"}\n"
	"\n"
	"/* Random number helpers */\n"
	"uint pcgHash(uint v) {\n"
	"	uint state = v * 747796405u + 2891336453u;\n"
	"	uint word  = ((state >> ((state >> 28u) + 4u)) ^ state) * 277803737u;\n"
	"	return (word >> 22u) ^ word;\n"
	"}\n"
	"\n"
	"float rand(inout uint seed) {\n"
	"	seed = pcgHash(seed);\n"
	"	return float(seed) * (1.0 / 4294967296.0);\n"
	"}\n"
	"\n"
	"/* Cosine weighted direction in the hemisphere around n */\n"
	"vec3 cosineSample(vec3 n, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float sr2 = sqrt(r2);\n"
	"	vec3 t = abs(n.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, n));\n"
	"	vec3 v = cross(n, u);\n"
	"	return normalize(u * (cos(phi) * sr2) + v * (sin(phi) * sr2) + n * sqrt(max(0.0, 1.0 - r2)));\n"
	"}\n"
	"\n"
	"/* Random direction inside a cone around dir, tan of half angle = tanRadius */\n"
	"vec3 coneSample(vec3 dir, float tanRadius, inout uint seed) {\n"
	"	float r1 = rand(seed);\n"
	"	float r2 = rand(seed);\n"
	"	float phi = 6.28318530718 * r1;\n"
	"	float r   = tanRadius * sqrt(r2);\n"
	"	vec3 t = abs(dir.x) > 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);\n"
	"	vec3 u = normalize(cross(t, dir));\n"
	"	vec3 v = cross(dir, u);\n"
	"	return normalize(dir + u * (cos(phi) * r) + v * (sin(phi) * r));\n"
	"}\n"
	"\n"
	"/* Light received from emitting blocks (lava, lamps...) by explicitly sampling one of them.\n"
	"   Picks an emitter with probability proportional to 1/distance^2, then traces a ray to it.\n"
	"   Noisy per frame, but the temporal accumulation and blur average it out. */\n"
	"vec3 emitterLight(vec3 p, vec3 n, inout uint seed) {\n"
	"	int count = window.w;\n"
	"	if (count == 0) return vec3(0.0);\n"
	"\n"
	"	float wsum = 0.0, chosenW = 0.0;\n"
	"	int chosen = -1;\n"
	"	for (int i = 0; i < count; i++) {\n"
	"		vec3 d = vec3(emitters[i].xyz) + 0.5 - p;\n"
	"		float d2 = dot(d, d);\n"
	"		if (d2 > 32.0 * 32.0 || dot(d, n) <= 0.0) continue;\n"
	"\n"
	"		float w = 1.0 / max(d2, 1.0);\n"
	"		wsum += w;\n"
	"		if (rand(seed) * wsum < w) { chosen = i; chosenW = w; }\n"
	"	}\n"
	"	if (chosen < 0) return vec3(0.0);\n"
	"\n"
	"	vec3  d    = vec3(emitters[chosen].xyz) + 0.5 - p;\n"
	"	float dist = length(d);\n"
	"	vec3  dir  = d / dist;\n"
	"	Hit eh;\n"
	"	if (!traceRay(p, dir, dist + 1.0, false, true, eh)) return vec3(0.0);\n"
	"	/* must have reached the emitter itself, not something in between */\n"
	"	if (ivec3(floor(eh.pos - eh.normal * 0.5)) != emitters[chosen].xyz) return vec3(0.0);\n"
	"\n"
	"	vec3  Le   = sampleTile(tileFor(eh.block, eh.face), eh.uv, 4.0).rgb * blocks[eh.block].tint.rgb * fogParams.z;\n"
	"	float cosR = max(dot(n, dir), 0.0);\n"
	"	float cosE = max(dot(-dir, eh.normal), 0.0);\n"
	"	float falloff = 1.0 / max(dist * dist, 1.0);\n"
	"	return Le * cosR * cosE * falloff * (wsum / chosenW) / 3.14159265;\n"
	"}\n"
	"\n"
	"/* Second composite pass: blends the translucent water layer over everything drawn so far\n"
	"   (opaque world, entities, particles), using premultiplied alpha. Writes the water\n"
	"   surface depth, like the rasteriser's translucent pass does. */\n"
	"layout(binding = 6) uniform sampler2D albedoTex;  /* w = distance to the water surface along the pixel ray */\n"
	"layout(binding = 7) uniform sampler2D waterTex;   /* rgb = premultiplied colour, a = alpha */\n"
	"\n"
	"out vec4 fragColour;\n"
	"\n"
	"void main() {\n"
	"	ivec2 px = ivec2(vec2(gl_FragCoord.xy) * vec2(screen.xy) / vec2(window.xy));\n"
	"	px = clamp(px, ivec2(0), screen.xy - 1);\n"
	"\n"
	"	float t = texelFetch(albedoTex, px, 0).a;\n"
	"	if (t <= 0.0) discard;\n"
	"	vec4 water = texelFetch(waterTex, px, 0);\n"
	"\n"
	"	/* Reconstruct the water surface position from the pixel's camera ray */\n"
	"	vec2 ndc = (vec2(px) + 0.5) / vec2(screen.xy) * 2.0 - 1.0;\n"
	"	vec4 pNear = invViewProj * vec4(ndc, -1.0, 1.0);\n"
	"	vec4 pFar  = invViewProj * vec4(ndc,  1.0, 1.0);\n"
	"	pNear.xyz /= pNear.w;\n"
	"	pFar.xyz  /= pFar.w;\n"
	"	vec3 pos = pNear.xyz + normalize(pFar.xyz - pNear.xyz) * t;\n"
	"\n"
	"	vec4  eye = view * vec4(pos, 1.0);\n"
	"	float fz  = abs(eye.z);\n"
	"	float f;\n"
	"	if (fogCol.w > 0.0) {\n"
	"		f = exp(-fogCol.w * fz);\n"
	"	} else {\n"
	"		f = clamp((fogParams.x - fz) / fogParams.x, 0.0, 1.0);\n"
	"	}\n"
	"	vec3 colour = mix(fogCol.rgb * water.a, water.rgb, f);\n"
	"\n"
	"	vec4 clip = viewProj * vec4(pos, 1.0);\n"
	"	gl_FragDepth = clamp((clip.z / clip.w) * 0.5 + 0.5, 0.0, 1.0);\n"
	"	fragColour = vec4(colour, water.a);\n"
	"}\n"
	"\n";

#endif
